const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='mapadeprovas.v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
let base;try{const r=await fetch('./data.json',{cache:'no-store'});if(!r.ok)throw Error();base=await r.json()}catch{$('#results').innerHTML='<div class="empty"><h3>Não foi possível carregar a base.</h3><p>Atualize a página para tentar novamente.</p></div>';throw Error('Data unavailable')}
let custom=saved.custom||{subjects:[],exams:[],questions:[]},progress=saved.progress||{},notes=saved.notes||{},materialLinks=cleanMaterialLinks(saved.materialLinks);const state={subject:'Tributário',area:'Todas',search:'',board:'',exam:'',common:false,sort:'alpha',view:'matrix',kandir:'',difference:'',page:'map',quality:'',transfer:'',studyTrack:'state-complement',coverage:'',includeAnnulled:false,accountingTheoryOpen:false};let activeQuestion=null;
function subjectCatalog(subject=state.subject){return (base.subjectCatalog||[]).find(c=>c.name===subject)}
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function data(){return{subjects:[...new Set([...base.subjects,...custom.subjects])],exams:[...base.exams,...custom.exams.filter(x=>!base.exams.some(e=>e.id===x.id))],questions:[...base.questions,...custom.questions.filter(x=>!base.questions.some(q=>q.id===x.id))]}}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({custom,progress,notes,materialLinks}));return true}catch{toast('Não foi possível salvar no navegador. Exporte uma cópia.');return false}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function currentExams(){const d=data(),used=new Set(d.questions.filter(q=>q.subject===state.subject).map(q=>q.examId));return d.exams.filter(e=>used.has(e.id)&&(!state.board||e.board===state.board)&&(!state.exam||e.id===state.exam))}
function groups(){const exams=currentExams(),ids=new Set(exams.map(e=>e.id)),d=data();const all=d.questions.filter(q=>q.subject===state.subject&&(state.area==='Todas'||q.area===state.area)&&ids.has(q.examId));const terms=normalize(state.search.trim());const map=new Map();for(const q of all){const comparison=kandirInfo(q);if(state.kandir&&comparison.status!==state.kandir)continue;if(state.difference&&!comparison.differences.includes(state.difference))continue;if(terms&&!normalize([q.topic,q.summary,q.number,q.examId,q.nature,q.body,q.sourceLabel,q.summaryCoverage?.neededKnowledge,q.summaryCoverage?.missingKnowledge,...(q.lawRefs||[]).flatMap(r=>[r.law,...r.articles]),comparison.label,comparison.base,comparison.complement,...comparison.differences].join(' ')).includes(terms))continue;const key=q.area+'|'+q.topic;if(!map.has(key))map.set(key,{area:q.area,topic:q.topic,questions:[]});map.get(key).questions.push(q)}let list=[...map.values()].filter(g=>!state.common||new Set(g.questions.map(q=>q.examId)).size>=2);const coverage=g=>new Set(g.questions.map(q=>q.examId)).size;list.sort((a,b)=>{const areaOrder=['Direito Tributário','Reforma','LTE'];const ar=areaOrder.indexOf(a.area)-areaOrder.indexOf(b.area);if(ar)return ar;if(state.sort==='coverage')return coverage(b)-coverage(a)||a.topic.localeCompare(b.topic,'pt-BR');if(state.sort==='questions')return b.questions.length-a.questions.length||a.topic.localeCompare(b.topic,'pt-BR');return a.topic.localeCompare(b.topic,'pt-BR')});return{list,exams}}
function renderNav(){const d=data();const diffOptions=[...new Set(d.questions.flatMap(q=>kandirInfo(q).differences))].sort((a,b)=>a.localeCompare(b,'pt-BR'));$('#difference').innerHTML='<option value="">Todos os complementos</option>'+diffOptions.map(t=>`<option value="${esc(t)}" ${state.difference===t?'selected':''}>${esc(t)}</option>`).join('');$('#subjects').innerHTML=d.subjects.map(s=>{const count=d.questions.filter(q=>q.subject===s).length,c=subjectCatalog(s);return `<button class="nav-item ${state.subject===s?'active':''}" data-subject="${esc(s)}"><span>▧</span><span class="nav-subject-label">${esc(s)}${!count&&c?'<small>Aguardando análise</small>':''}</span><span class="count" title="${!count&&c?'Questões identificadas nos cadernos, ainda sem análise':'Questões no mapa'}">${!count&&c?c.availableCount:count}</span></button>`}).join('');$('#breadcrumb').textContent=state.subject;const qs=d.questions.filter(q=>q.subject===state.subject);const areas=['Todas',...new Set(qs.map(q=>q.area))];$('#areas').innerHTML=areas.map(a=>`<button class="tab ${state.area===a?'active':''}" data-area="${esc(a)}">${esc(a)}<span>${a==='Todas'?qs.length:qs.filter(q=>q.area===a).length}</span></button>`).join('');const available=d.exams.filter(e=>(qs.some(q=>q.examId===e.id)||subjectCatalog()?.sourceQuestions.some(q=>q.examId===e.id))&&(!state.board||e.board===state.board));if(state.exam&&!available.some(e=>e.id===state.exam))state.exam='';$('#exam').innerHTML='<option value="">Todas</option>'+available.map(e=>`<option value="${esc(e.id)}" ${e.id===state.exam?'selected':''}>${esc(e.name)} · ${esc(e.year)}</option>`).join('');const boards=[...new Set(d.exams.map(e=>e.board))];$('#board').innerHTML='<option value="">Todas</option>'+boards.map(b=>`<option ${b===state.board?'selected':''}>${esc(b)}</option>`).join('')}
function kandirInfo(q){return q.kandir||{status:'pending',label:'Comparação pendente',articles:[],base:'Esta questão ainda não recebeu análise da relação com a Lei Kandir.',complement:'O conteúdo foi adicionado depois da análise inicial. A classificação deve ser feita pelo conteúdo, e não apenas por palavras-chave.',study:'Peça a análise desta questão para completar os campos.',differences:[]}}
function comparisonMini(q){const k=kandirInfo(q);const hasBase=['yes','partial'].includes(k.status);const general=q.nature==='Nacional'&&!hasBase&&k.status!=='pending';return `<div class="comparison-mini"><span class="base-tag ${hasBase||general?'is-base':''}">${hasBase?'● Base: Kandir':general?'● Base: outra norma nacional':k.status==='pending'?'◷ Comparação pendente':k.status==='no'?'◆ Detalhe fora da Kandir':'○ Fora do ICMS'}</span>${k.differences.filter(t=>!['Regra nacional reproduzida','Outra base normativa','Outra norma nacional'].includes(t)).slice(0,3).map(t=>`<span class="difference-tag ${q.nature==='Estadual'?'local':'national'}">${esc(t)}</span>`).join('')}${k.differences.filter(t=>!['Regra nacional reproduzida','Outra base normativa','Outra norma nacional'].includes(t)).length>3?'<span class="more-tags">+ detalhes</span>':''}</div>`}
function comparisonPanel(q){const k=kandirInfo(q);const baseClass=['yes','partial'].includes(k.status)?'has-base':k.status==='pending'?'pending-base':'other-base';return `<section class="comparison-panel"><div class="comparison-title"><h3>Base nacional × complemento</h3><span class="comparison-status ${baseClass}">${esc(k.label)}</span></div><div class="base-box ${baseClass}"><span class="box-caption">CONTEÚDO-BASE</span><p>${esc(k.base)}</p>${k.articles.length?`<div class="article-pills">${k.articles.map(a=>`<span>${esc(a)}</span>`).join('')}</div><a href="https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp87.htm" target="_blank" rel="noopener noreferrer">Consultar Lei Kandir no Planalto ↗</a>`:''}</div><div class="complement-box"><span class="box-caption">${q.nature==='Estadual'?'O QUE A COBRANÇA ESTADUAL ACRESCENTA':'O QUE COMPLETA A RESPOSTA'}</span><p>${esc(k.complement)}</p><div class="difference-tags">${k.differences.map(t=>`<span class="difference-tag ${q.nature==='Estadual'?'local':'national'}">${esc(t)}</span>`).join('')}</div></div><div class="study-next"><strong>Para estudar esta questão</strong><p>${esc(k.study)}</p></div><p class="comparison-footnote">Classificação para estudo; as etiquetas não afirmam que a única diferença é o item marcado. A legislação estadual complementa a base nacional dentro de seus limites.</p></section>`}
function answerLabel(q){return q.answer?(['Anulada','Desatualizada'].includes(q.answer)?q.answer:'Gabarito '+q.answer):'Gabarito não informado'}
function answerBadge(q){return `<span class="answer-badge ${q.answer==='Anulada'?'cancelled':''} ${!q.answer?'missing':''}">${esc(answerLabel(q))}</span>`}
function answerPanel(q){const src=q.answerSource;return `<section class="answer-panel ${q.answer==='Anulada'?'cancelled':''}"><span class="answer-letter">${esc(q.answer||'?')}</span><div><strong>${q.answer==='Anulada'?'Questão anulada no caderno':q.answer==='Desatualizada'?'Questão indicada como desatualizada':q.answer?'Alternativa correta: '+esc(q.answer):'Gabarito não informado'}</strong><p>${src?`Fonte: ${esc(src.file)}${src.pages?.length?' · página'+(src.pages.length>1?'s ':' ')+src.pages.join(', '):''}. Numeração do TEC.`:'Adicione o gabarito ao cadastrar a questão.'}</p>${src?'<small>Reproduzido do material enviado, sem revisão independente do gabarito oficial.</small>':''}</div></section>`}
function questionBodyHTML(q){const text=q.body||q.originalText||'Texto não adicionado.';const matches=[...text.matchAll(/(^|\n)([a-e])\)[ \t]*/g)];if(!matches.length)return esc(text);let html=esc(text.slice(0,matches[0].index));for(let i=0;i<matches.length;i++){const m=matches[i],end=i+1<matches.length?matches[i+1].index:text.length,letter=m[2].toUpperCase(),correct=q.answer===letter;html+=`<div class="answer-option ${correct?'correct-option':''}">${correct?'<span class="correct-caption">✓ ALTERNATIVA DO GABARITO</span>':''}${esc(text.slice(m.index,end).trim())}</div>`}return html}
function taxCard(q){return `<button class="question-card" data-q="${esc(q.id)}"><span class="qtop"><span class="qnum">Q${esc(q.number)}</span>${literalidadeBadge(q)}<span class="nature">${esc(q.nature)}</span>${progress[q.id]&&progress[q.id]!=='Não estudada'?'<span class="qprogress" title="'+esc(progress[q.id])+'">'+(progress[q.id]==='Revisada'?'✓':'◐')+'</span>':''}</span><p>${esc(questionPreview(q))}</p>${answerBadge(q)}${coverageMini(q)}${qualityInfo(q).status==='omission'?qualityTag(q):''}${comparisonMini(q)}</button>`}
function questionPreview(q){const b=(q.body||'').replace(/\s+/g,' ').replace(/^Atenção:[\s\S]*?(?=Segundo|Conforme|Relativamente|O |A |São |No |Os )/,'');return b.length>35?b.slice(0,230):q.summary}
function renderMap(){renderNav();const{list,exams}=groups(),visible=list.flatMap(g=>g.questions),used=new Set(visible.map(q=>q.examId)),seen=visible.filter(q=>['Estudada','Revisada'].includes(progress[q.id])).length;$('#stats').innerHTML=[['▧',list.length,'conteúdos encontrados'],['≡',visible.length,'questões no filtro'],['◫',used.size,'provas comparadas'],['✓',seen,'questões estudadas']].map(([i,n,l])=>`<div class="stat"><span class="stat-icon">${i}</span><div><strong>${n}</strong><small>${l}</small></div></div>`).join('');$('#resultCount').textContent=`${list.length} conteúdos · ${visible.length} questões${state.common?' · presentes em 2 ou mais provas':''}`;$('#matrixView').classList.toggle('active',state.view==='matrix');$('#listView').classList.toggle('active',state.view==='list');if(!list.length){$('#results').innerHTML=portugueseIncidenceOverview()+`<div class="empty"><h3>${data().questions.some(q=>q.subject===state.subject)?'Nenhum conteúdo com esses filtros.':'Uma nova matéria começa aqui.'}</h3><p>${state.common?'Tente desativar “Só conteúdos em comum” ou selecionar mais provas.':'Adicione uma questão ou importe uma base para organizar os conteúdos.'}</p><button class="secondary" data-action="reset">Limpar filtros</button></div>`;return}if(state.view==='list'){$('#results').innerHTML=portugueseIncidenceOverview()+accountingTheoryOverview(visible)+'<div class="topic-list">'+list.map(g=>`<article class="topic-block"><small>${esc(g.area)} · ${new Set(g.questions.map(q=>q.examId)).size} provas</small><h3>${topicStudyTitle(g)}</h3><div class="topic-chips">${g.questions.map(q=>{const e=exams.find(e=>e.id===q.examId);return`<button class="${accountingQuestionClass(q)}" data-q="${esc(q.id)}">${esc(e?.name||q.examId)} · Q${esc(q.number)} ${literalidadeBadge(q)}${q.subject!=='Tributário'?cfcBadge(q):''}${accountingBadge(q)} ↗<span class="list-base">${esc(q.subject==='Tributário'?kandirInfo(q).label:q.summary)}</span>${answerBadge(q)}</button>`}).join('')}</div></article>`).join('')+'</div>';return}let area='';$('#results').innerHTML=portugueseIncidenceOverview()+accountingTheoryOverview(visible)+`<div class="matrix-wrap"><table><thead><tr><th scope="col">Conteúdo<small>Mesma linha = mesmo tema principal</small></th>${exams.map(e=>`<th scope="col">${esc(e.name)}<small>${esc(e.board)} · ${esc(e.year)}</small></th>`).join('')}</tr></thead><tbody>${list.map(g=>{let section='';if(g.area!==area){area=g.area;section=`<tr class="section-row"><th colspan="${exams.length+1}">${esc(area)}</th></tr>`}const coverage=new Set(g.questions.map(q=>q.examId)).size;return section+`<tr><th scope="row">${topicStudyTitle(g)}<small>${g.questions.length} ${g.questions.length===1?'questão':'questões'} · ${coverage} ${coverage===1?'prova':'provas'}</small></th>${exams.map(e=>{const qs=g.questions.filter(q=>q.examId===e.id).sort((a,b)=>a.number-b.number);return`<td>${qs.length?qs.map(card).join(''):'<span class="dash" aria-label="Sem questão identificada neste conteúdo">—</span>'}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div>`}
function taxOpenQuestion(id){const q=data().questions.find(q=>q.id===id);if(!q)return;activeQuestion=id;const e=data().exams.find(e=>e.id===q.examId);$('#detailEyebrow').textContent=`${e?.name||q.examId} · ${e?.board||''} · ${e?.year||''}`;$('#detailContent').innerHTML=`<div class="detail-inner"><h2>Questão ${esc(q.number)} ${literalidadeBadge(q)}<br>${esc(q.topic)}</h2><div class="badges"><span class="badge">${esc(q.subject)}</span><span class="badge">${esc(q.area)}</span><span class="badge">${esc(q.nature)}</span></div><p class="detail-summary">${esc(q.summary)}</p>${transferPanel(q)}${comparisonPanel(q)}${coveragePanel(q)}${sourceCheckHTML(q)}<div class="detail-divider"></div><h3>Texto do caderno</h3>${answerPanel(q)}<div class="question-body">${questionBodyHTML(q)}</div>${q.url?`<a class="source-link" href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">Abrir questão no TEC ↗</a>`:''}<p class="save-caption">Texto extraído do PDF. Fórmulas ou imagens podem não aparecer integralmente. Gabarito reproduzido do caderno enviado.</p><div class="detail-divider"></div><h3>Seu acompanhamento</h3><div class="status-buttons">${['Não estudada','Estudada','Revisada'].map(s=>`<button data-status="${s}" class="${(progress[id]||'Não estudada')===s?'active':''}">${s}</button>`).join('')}</div><h3 style="margin-top:24px">Suas anotações</h3><textarea id="questionNotes" placeholder="Anote uma dúvida, diferença da regra estadual ou ponto para revisar…">${esc(notes[id]||'')}</textarea><p class="save-caption" id="noteCaption">Salvas automaticamente neste navegador. Use Exportar para guardar uma cópia.</p></div>`;$('#detail').showModal()}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=html;$('#modal').showModal()}
$('#results').addEventListener('click',e=>{const q=e.target.closest('[data-q]');if(q)openQuestion(q.dataset.q);const law=e.target.closest('[data-law]');if(law)openLaw(law.dataset.law);const material=e.target.closest('[data-material]');if(material)openMaterial(material.dataset.material);if(e.target.closest('[data-action="reset"]'))reset()});$('#subjects').addEventListener('click',e=>{const b=e.target.closest('[data-subject]');if(b){state.subject=b.dataset.subject;state.cfcStatus='';state.page='map';state.board='';state.coverage='';state.quality='';state.transfer='';state.common=false;$('#common').checked=false;state.kandir='';state.difference='';$('#kandir').value='';state.area='Todas';state.exam='';state.search='';$('#search').value='';render()}});$('#areas').addEventListener('click',e=>{const b=e.target.closest('[data-area]');if(b){state.area=b.dataset.area;render()}});$('#search').addEventListener('input',e=>{state.search=e.target.value;render()});for(const id of ['board','exam','sort','kandir','difference'])$('#'+id).addEventListener('change',e=>{state[id]=e.target.value;render()});$('#common').addEventListener('change',e=>{state.common=e.target.checked;render()});$('#matrixView').onclick=()=>{state.view='matrix';render()};$('#listView').onclick=()=>{state.view='list';render()};function reset(){Object.assign(state,{area:'Todas',search:'',board:'',exam:'',common:false,sort:'alpha',kandir:'',difference:''});$('#search').value='';$('#common').checked=false;$('#sort').value='alpha';$('#kandir').value='';$('#difference').value='';render()}$('#reset').onclick=reset;document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus()}});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#detail').addEventListener('click',e=>{const b=e.target.closest('[data-status]');if(b){progress[activeQuestion]=b.dataset.status;persist();$('#detail').querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('active',x===b));render()}});$('#detail').addEventListener('input',e=>{if(e.target.id==='questionNotes'){notes[activeQuestion]=e.target.value;const ok=persist();$('#noteCaption').textContent=ok?'Anotação salva neste navegador.':'Não foi possível salvar. Exporte sua cópia.'}});
$('#method').onclick=()=>modal('Como ler o mapa',`<p>${esc(base.methodology)}</p><div class="info-panel"><strong>O que significam as divisões?</strong><p><b>Direito Tributário:</b> Constituição, CTN e jurisprudência geral.</p><p><b>Reforma:</b> IBS/CBS, IS e normas de implementação.</p><p><b>LTE:</b> leis estaduais e normas nacionais relacionadas, como Kandir, LC 24 e Simples. O selo da questão distingue “Nacional” e “Estadual”.</p></div><div class="info-panel"><strong>Azul: conteúdo-base · Âmbar: complemento estadual</strong><p>${esc(base.comparisonMethod||'')}</p><p>Outra norma nacional é exibida em azul claro. Questões adicionadas manualmente ficam com comparação pendente até serem analisadas.</p></div><p><b>Mesma linha:</b> aproximação por conteúdo principal, sem afirmar que as questões exigem exatamente a mesma regra. Assuntos secundários continuam visíveis no texto.</p><p><b>Traço:</b> nenhuma questão identificada para esse tema no recorte, e não ausência garantida na prova oficial.</p><p>As observações sobre FCC, Cebraspe e FGV são limitadas aos cadernos analisados; conteúdo do edital, ano e seleção de questões também interferem.</p><p><b>Anotações e marcações:</b> ficam somente neste navegador. A base inicial é fixa; seus acréscimos locais podem ser guardados pelo botão Exportar e restaurados por Importar.</p>`);
$('#backup').onclick=()=>{const d=data();const blob=new Blob([JSON.stringify({...d,schemaVersion:1,progress,notes,materialLinks,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mapa-de-provas-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Base e anotações exportadas.')};$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>15e6)throw Error('Arquivo maior que 15 MB.');const d=JSON.parse(await f.text());if(d.schemaVersion!==1||!Array.isArray(d.questions)||!Array.isArray(d.exams)||!Array.isArray(d.subjects))throw Error('Formato inválido. Use um backup exportado pelo app.');const ex=new Set([...data().exams,...d.exams].map(e=>e.id));if(d.exams.some(e=>!e.id||!e.name||!e.board)||d.questions.some(q=>!q.id||!q.subject||!q.area||!q.topic||!ex.has(q.examId)||!Number.isInteger(q.number)||q.number<1||(q.url&&!/^https:\/\//.test(q.url))))throw Error('Há questões ou provas com dados inválidos.');const ids=new Set(data().questions.map(q=>q.id));const fresh=d.questions.filter(q=>!ids.has(q.id));custom.subjects=[...new Set([...custom.subjects,...d.subjects,...d.questions.map(q=>q.subject)])];for(const x of d.exams)if(!data().exams.some(e=>e.id===x.id))custom.exams.push(x);custom.questions.push(...fresh);Object.assign(progress,d.progress||{});Object.assign(notes,d.notes||{});Object.assign(materialLinks,cleanMaterialLinks(d.materialLinks));persist();render();toast(`${fresh.length} questões novas importadas. Anotações atualizadas.`)}catch(err){toast(err.message||'Não foi possível importar.')}e.target.value=''};
$('#newSubject').onclick=()=>{modal('Adicionar matéria',`<form id="subjectForm"><p>Crie uma matéria e depois acrescente suas questões. Os conteúdos ficam separados no menu.</p><div class="form-grid"><label class="full">Nome da matéria<input name="subject" required maxlength="70" placeholder="Ex.: Contabilidade Geral" autofocus></label></div><div class="form-actions"><button class="primary">Criar matéria</button></div></form>`);$('#subjectForm').onsubmit=e=>{e.preventDefault();const s=new FormData(e.target).get('subject').trim();if(!s)return;if(!data().subjects.includes(s))custom.subjects.push(s);state.subject=s;state.area='Todas';state.exam='';state.board='';persist();$('#modal').close();render();toast('Matéria criada. Adicione sua primeira questão.')}};
$('#addQuestion').onclick=()=>{const d=data(),topics=[...new Set(d.questions.filter(q=>q.subject===state.subject).map(q=>q.topic))];modal('Adicionar questão',`<form id="questionForm"><div class="form-grid"><label>Matéria<select name="subject">${d.subjects.map(s=>`<option ${s===state.subject?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Divisão / área<input name="area" list="areaOptions" required value="${state.area==='Todas'?'LTE':esc(state.area)}"><datalist id="areaOptions">${[...new Set(d.questions.map(q=>q.area))].map(a=>`<option value="${esc(a)}">`).join('')}</datalist></label><label class="full">Conteúdo principal<input name="topic" required list="topicOptions" placeholder="Ex.: Depreciação"><datalist id="topicOptions">${topics.map(t=>`<option value="${esc(t)}">`).join('')}</datalist></label><label>Prova<select name="examId">${d.exams.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} · ${esc(e.year)}</option>`).join('')}<option value="__new">＋ Outra prova</option></select></label><label>Número da questão<input name="number" type="number" min="1" required></label><label id="newExamFields" class="full" hidden>Nova prova (nome, banca e ano)<input name="newName" placeholder="Ex.: SEFAZ MG"><input name="newBoard" placeholder="Ex.: FGV"><input name="newYear" type="number" min="1990" max="2100" placeholder="Ano"></label><label>Tipo de norma<select name="nature"><option>Nacional</option><option>Estadual</option><option>Não se aplica</option></select></label><label>Gabarito<select name="answer"><option value="">Não informado</option><option>A</option><option>B</option><option>C</option><option>D</option><option>E</option><option>Anulada</option><option>Desatualizada</option></select></label><label>Link da questão (opcional)<input name="url" type="url" placeholder="https://…"></label><label class="full">O que foi cobrado<textarea name="summary" required placeholder="Descreva a cobrança específica desta questão."></textarea></label><label class="full">Texto da questão (opcional)<textarea name="body" placeholder="Cole o enunciado e as alternativas."></textarea></label></div><div class="form-error" id="formError"></div><div class="form-actions"><button class="primary">Adicionar ao mapa</button></div></form>`);const form=$('#questionForm');form.elements.examId.onchange=e=>$('#newExamFields').hidden=e.target.value!=='__new';form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));let examId=v.examId;if(examId==='__new'){if(!v.newName.trim()||!v.newBoard.trim()||!v.newYear){$('#formError').textContent='Preencha nome, banca e ano da prova.';return}examId='custom-'+crypto.randomUUID();}if(data().questions.some(q=>q.examId===examId&&q.number===Number(v.number)&&q.subject===v.subject)){$('#formError').textContent='Já existe uma questão com esse número nesta matéria e prova.';return}if(v.url&&!v.url.startsWith('https://')){$('#formError').textContent='Use um link iniciado por https://.';return}if(v.examId==='__new')custom.exams.push({id:examId,name:v.newName.trim(),board:v.newBoard.trim(),year:Number(v.newYear),source:'Adicionada manualmente'});custom.questions.push({id:'q-'+crypto.randomUUID(),examId,number:Number(v.number),subject:v.subject,area:v.area.trim(),topic:v.topic.trim(),nature:v.nature,summary:v.summary.trim(),body:v.body.trim(),url:v.url.trim(),sourceLabel:'Adicionada manualmente',answer:v.answer||undefined});persist();state.subject=v.subject;state.area='Todas';state.exam='';state.board='';state.common=false;$('#common').checked=false;$('#modal').close();render();toast('Questão adicionada ao conteúdo.')}};
const coverageLabels={sufficient:'Resumo sustenta o núcleo',partial:'Resumo + complemento',notfound:'Regra não localizada',annulled:'Questão anulada',pending:'A conferir'};
function coverageInfo(q){return q.coverage||{status:'pending',reason:'Questão adicionada após a análise dos materiais; a cobertura ainda precisa ser verificada.',summaryEvidence:[],lawEvidence:[]}}
const complementLabels={state:'L + estadual',national:'L + base nacional',review:'L parcial · a conferir'};
function partialType(q){return coverageInfo(q).complementType||'review'}
function coverageLabel(q){const c=coverageInfo(q);return c.status==='partial'?complementLabels[partialType(q)]:(coverageLabels[c.status]||'A conferir')}
function coverageMatches(q,value){return !value||(['partial-state','partial-national','partial-review'].includes(value)?coverageInfo(q).status==='partial'&&partialType(q)===value.slice(8):coverageInfo(q).status===value)}
function partialBreakdown(qs){const result={state:0,national:0,review:0};for(const q of qs)if(coverageInfo(q).status==='partial')result[partialType(q)]++;return result}
const resolutionLabels={'rule-mapped':'Regra mapeada no resumo',elimination:'Suficiente por eliminação','prompt-combination':'Resumo + informação do enunciado','conceptual-application':'Aplicação dos conceitos do resumo','jurisprudence-complement':'Complemento jurisprudencial','statutory-omission':'Regra legal não localizada no resumo'};
function resolutionPanel(q){const review=q.dtReview||q.lteReview;if(!review)return '';const c=coverageInfo(q);return `<div class="resolution-panel"><strong>Revisão de ${q.area==='LTE'?'LTE':'Direito Tributário'} · ${esc(resolutionLabels[review.route]||({['state-complement']:'Complemento estadual identificado',['other-national']:'Outra norma nacional',['source-pending']:'Fonte específica ainda a conferir',annulled:'Anulada'}[review.route])||'Conferência da regra decisiva')}</strong><p>${c.status==='sufficient'?'O material permite identificar a resposta por esta rota. Isso não significa que contenha todas as teses de todos os itens.':'A regra faltante permanece separada e identificada.'}</p>${c.uncoveredExtra?`<p><b>Detalhe não certificado no resumo:</b> ${esc(c.uncoveredExtra)}</p>`:''}</div>`}
function dtAuditHTML(qs){const dt=qs.filter(q=>q.area==='Direito Tributário'&&q.dtReview);if(!dt.length)return '';const counts=coverageCounts(dt),routes={};for(const q of dt)routes[q.dtReview.route]=(routes[q.dtReview.route]||0)+1;return `<section class="dt-audit"><h3>Direito Tributário — revisão das questões</h3><p><strong>${counts.sufficient} de ${dt.length} questões respondíveis com os resumos neste recorte (${(counts.sufficient/dt.length*100).toFixed(1).replace('.',',')}%).</strong> ${routes['rule-mapped']||0} têm regra mapeada; ${routes.elimination||0} permitem eliminação; ${routes['prompt-combination']||0} combinam o resumo com informação fornecida no enunciado; ${routes['conceptual-application']||0} exigem aplicação dos conceitos.</p><p>A marcação anterior era conservadora ao exigir a tese literal de todos os itens. Agora, a rota fica explícita. Continua sendo uma estimativa de suficiência, não um acerto pessoal medido.</p>${dt.some(q=>q.id==='CE-76')?'<p><strong>CE-76:</strong> art. 210 do CTN localizado na lei enviada, não nos resumos pesquisados. <strong>PR-64:</strong> tese específica sobre número de empregados e base da taxa não localizada no resumo; complemento jurisprudencial.</p>':''}<details><summary>Ver a conferência de cada questão</summary><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Questão</th><th>Rota / conclusão</th><th>Páginas dos resumos</th></tr></thead><tbody>${dt.map(q=>`<tr><th>${questionChip(q)}<small>${esc(q.topic)}</small></th><td>${esc(resolutionLabels[q.dtReview.route])}${q.coverage.uncoveredExtra?`<p>${esc(q.coverage.uncoveredExtra)}</p>`:''}</td><td>${q.dtReview.evidencePages.map(ev=>`${esc(materialById(ev.materialId)?.filename||'Resumo')} · p. ${ev.page}`).join('<br>')||'Regra faltante não localizada nos resumos'}<button class="evidence-open" data-q="${esc(q.id)}">Ver trecho e raciocínio ↗</button></td></tr>`).join('')}</tbody></table></div></details></section>`}
function literalidadeBadge(q){const status=coverageInfo(q).status;if(q.answer==='Anulada'||!['sufficient','partial'].includes(status))return '';const partial=status==='partial';const route=coverageInfo(q).resolutionRoute;const label=partial?'L parcial: '+complementLabels[partialType(q)]:'L: '+(resolutionLabels[route]||'regra decisiva localizada no resumo do Literalidade');return `<span class="literalidade-seal ${partial?'partial':''}" title="${label}" aria-label="${label}">L${partial?'<small>'+({state:'+ estadual',national:'+ nacional',review:'a conferir'}[partialType(q)])+'</small>':route?'<small>'+({elimination:'eliminação','prompt-combination':'enunciado','conceptual-application':'aplicação'}[route]||'')+'</small>':''}</span>`}
function coverageMini(q){const c=coverageInfo(q);return `<span class="coverage-tag ${c.status}">${esc(coverageLabel(q))}</span>`}
function materialById(id){return(base.materials||[]).find(m=>m.id===id)}
function evidenceHTML(ev,kind){const m=materialById(ev.materialId);return `<article class="evidence"><div><span class="evidence-kind">${kind==='summary'?'RESUMO':'LEI / TEXTO NORMATIVO'}</span><strong>${esc(m?.title||ev.materialId)}</strong><small>Página ${ev.page} do PDF enviado</small></div><blockquote>${esc(ev.excerpt)}</blockquote></article>`}
function refsHTML(q){return(q.lawRefs||[]).map(r=>`<div class="law-ref"><strong>${esc(r.law)}</strong><span>${r.articles?.length?r.articles.map(a=>'Art. '+esc(a)).join(' · '):'Artigo a conferir'}${r.precision==='thematic'?' · faixa/referência temática':''}</span></div>`).join('')||'<p class="muted">Referência legal a conferir.</p>'}
function coveragePanel(q){const c=coverageInfo(q);return `<section class="coverage-panel"><div class="comparison-title"><h3>Se eu estudasse só pelo resumo?</h3>${coverageMini(q)}</div><p>${esc(c.reason)}</p>${resolutionPanel(q)}${c.status==='partial'?`<p class="complement-next"><strong>${esc(complementLabels[partialType(q)])}</strong><br>${esc(c.complementAssessment?.nextStep||'Verificar qual complemento é necessário.')}</p>`:''}${c.temporalReview?'<p class="temporal-note">◷ Atenção ao recorte temporal: material atualizado depois da prova.</p>':''}<div class="law-refs">${refsHTML(q)}</div>${(c.summaryEvidence||[]).map(ev=>evidenceHTML(ev,'summary')).join('')}${(c.lawEvidence||[]).map(ev=>evidenceHTML(ev,'law')).join('')}${(c.verifiedSources||[]).length?`<div class="verified-sources"><h4>Fontes oficiais conferidas</h4>${c.verifiedSources.map(v=>`<article><a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${esc(v.title)} ↗</a><strong>${esc(v.articles)}</strong><p>${esc(v.note)}</p></article>`).join('')}</div>`:''}${c.reviewAudit?`<p class="review-audit">✓ Regra decisiva conferida em 17/10/2026 · ${esc(c.reviewAudit.result)}. ${esc(c.reviewAudit.method)}</p>`:''}<p class="comparison-footnote">A classificação compara a regra ou rota suficiente de resolução, não garante acerto e não certifica todos os distratores. A busca sem resultado é limitada aos arquivos enviados.</p></section>`}
function selectedQuestions(){return groups().list.flatMap(g=>g.questions)}
function coverageCounts(qs){const counts={sufficient:0,partial:0,notfound:0,annulled:0,pending:0};for(const q of qs)counts[coverageInfo(q).status]=(counts[coverageInfo(q).status]||0)+1;return counts}
function statsHTML(items){$('#stats').innerHTML=items.map(([n,l])=>`<div class="stat"><span class="stat-icon">◫</span><div><strong>${esc(n)}</strong><small>${esc(l)}</small></div></div>`).join('')}
function questionChip(q){return `<button class="q-chip" data-q="${esc(q.id)}">${esc(q.examId)} · Q${q.number}${q.answer?' · '+esc(q.answer):''} ${literalidadeBadge(q)}</button>`}
function contentCoverage(qs){const groups=new Map();for(const q of qs){const key=JSON.stringify([q.area,q.topic]);if(!groups.has(key))groups.set(key,{area:q.area,topic:q.topic,questions:[]});groups.get(key).questions.push(q)}return [...groups.values()].map(g=>{const counts=coverageCounts(g.questions),valid=g.questions.length-counts.annulled;return {...g,counts,valid,percent:valid?Math.round(counts.sufficient/valid*100):null}}).sort((a,b)=>a.area.localeCompare(b.area,'pt-BR')||a.topic.localeCompare(b.topic,'pt-BR'))}
function contentCoverageHTML(all){const groups=contentCoverage(all).filter(g=>!state.coverage||g.questions.some(q=>coverageMatches(q,state.coverage)));return `<section class="content-score"><h3>Quanto os resumos cobrem por conteúdo?</h3><p>O placar conta questões com <strong>L</strong>: regra mapeada ou rota suficiente explicitada no detalhe. L + estadual: falta a regra local. L + base nacional: falta complementar norma nacional, jurisprudência ou conceito geral. Complemento a conferir: a análise ainda não permite separar com segurança. Questões anuladas ficam fora do total válido; pendentes permanecem no total, sem contar como cobertas.</p><div class="coverage-table-wrap"><table class="coverage-table content-score-table"><thead><tr><th>Conteúdo</th><th>Só com os resumos · L</th><th>Cobertura</th><th>L + estadual</th><th>L + base nacional</th><th>Complemento a conferir</th><th>Não localizada</th><th>A conferir</th><th>Questões por resultado</th></tr></thead><tbody>${groups.map(g=>`<tr><th><small>${esc(g.area)}</small>${esc(g.topic)}${g.counts.annulled?`<small>${g.counts.annulled} anulada(s) excluída(s)</small>`:''}</th><td><strong>${g.counts.sufficient} de ${g.valid}</strong></td><td><strong>${g.percent===null?'—':g.percent+'%'}</strong><div class="coverage-bar"><i style="width:${g.percent||0}%"></i></div></td><td>${partialBreakdown(g.questions).state}</td><td>${partialBreakdown(g.questions).national}</td><td>${partialBreakdown(g.questions).review}</td><td>${g.counts.notfound}</td><td>${g.counts.pending}</td><td><details><summary>Ver ${g.questions.length} questões</summary>${['sufficient','partial','notfound','pending','annulled'].map(status=>{const qs=g.questions.filter(q=>coverageInfo(q).status===status);return qs.length?`<div class="content-question-group"><small>${esc(coverageLabels[status])}</small>${qs.map(questionChip).join(' ')}</div>`:''}).join('')}</details></td></tr>`).join('')}</tbody></table></div><p class="save-caption">Estimativa de suficiência do material, não medição de acertos. A comparação reúne as provas selecionadas e usa os resumos enviados, inclusive materiais posteriores à data de algumas provas.</p></section>`}
function renderCoverage(){renderNav();const all=selectedQuestions(),counts=coverageCounts(all),valid=all.length-counts.annulled,pct=valid?Math.round(counts.sufficient/valid*100):0;statsHTML([[counts.sufficient,'resumo sustenta o núcleo'],[counts.partial,'exigem complemento'],[counts.notfound,'regras não localizadas'],[pct+'%','do recorte válido · retrospectivo']]);let rows=all.filter(q=>coverageMatches(q,state.coverage));rows.sort((a,b)=>a.area.localeCompare(b.area,'pt-BR')||a.topic.localeCompare(b.topic,'pt-BR')||a.examId.localeCompare(b.examId)||a.number-b.number);$('#resultCount').textContent=`${rows.length} questões exibidas · ${counts.annulled} anuladas fora do índice`;const areas=[...new Set(all.map(q=>q.area))];$('#results').innerHTML=`<div class="assessment-notice"><strong>O resumo contém a regra necessária?</strong><p>A resposta é por questão, com trecho e página. A revisão por fontes está separada na aba Qualidade dos resumos, que distingue a cobertura da prova da fidelidade do material. Abra cada questão para ver a fonte conferida. “Sustenta o núcleo” é uma avaliação do conteúdo, não garantia de acerto. Os materiais de 2026 podem ser posteriores às provas de 2025. ${counts.pending?'Há questões pendentes de análise.':''}</p></div><div class="area-coverage">${areas.map(a=>{const qs=all.filter(q=>q.area===a),c=coverageCounts(qs),den=qs.length-c.annulled;return `<article><strong>${esc(a)}</strong><span>${c.sufficient} de ${den} com núcleo no resumo</span><div class="coverage-bar"><i style="width:${den?c.sufficient/den*100:0}%"></i><b style="width:${den?c.partial/den*100:0}%"></b></div><small>${c.partial} complemento · ${c.notfound} não localizadas · ${c.annulled} anuladas</small></article>`}).join('')}</div>${dtAuditHTML(all)}${lteAuditHTML(all)}${contentCoverageHTML(all)}<h3 class="question-evidence-title">Conferência questão por questão</h3>${!rows.length?'<div class="empty"><h3>Nenhuma questão com este filtro.</h3></div>':`<div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Conteúdo / questão</th><th>Conclusão e próximo passo</th><th>Resumo / página</th><th>Lei e artigos</th></tr></thead><tbody>${rows.map(q=>{const c=coverageInfo(q);return `<tr><th><small>${esc(q.area)}</small>${esc(q.topic)}<div>${questionChip(q)}</div></th><td>${coverageMini(q)}<p>${esc(c.reason)}</p>${resolutionPanel(q)}${c.status==='partial'?`<p class="complement-next"><strong>${esc(complementLabels[partialType(q)])}</strong><br>${esc(c.complementAssessment?.nextStep||'Verificar qual complemento é necessário.')}</p>`:''}${c.temporalReview?'<span class="temporal-small">Recorte temporal a conferir</span>':''}</td><td>${c.summaryEvidence?.length?c.summaryEvidence.map(ev=>{const m=materialById(ev.materialId);return `<button class="material-evidence-link" data-q="${esc(q.id)}">${esc(m?.title||'Resumo')}<small>Página ${ev.page} · ver trecho ↗</small></button>`}).join(''):'<span class="muted">Não localizado nos resumos enviados.</span>'}${c.lawEvidence?.length?'<small class="has-law">Há trecho de lei no detalhe.</small>':''}</td><td>${refsHTML(q)}</td></tr>`}).join('')}</tbody></table></div>`}`}
function lawStats(qs,includeAnnulled=false){const map=new Map();for(const q of qs){if(!includeAnnulled&&q.answer==='Anulada')continue;for(const r of q.lawRefs||[]){if(!map.has(r.law))map.set(r.law,{law:r.law,questions:new Map(),articles:new Map(),unconfirmed:new Map(),thematic:[]});const l=map.get(r.law);l.questions.set(q.id,q);if(r.precision==='identified'&&r.articles.length){for(const article of new Set(r.articles)){if(!l.articles.has(article))l.articles.set(article,new Map());l.articles.get(article).set(q.id,q)}}else{l.unconfirmed.set(q.id,q);if(r.articles.length)l.thematic.push({q,articles:r.articles})}}}return [...map.values()].sort((a,b)=>b.questions.size-a.questions.size||a.law.localeCompare(b.law,'pt-BR'))}
function renderLaws(){renderNav();const qs=selectedQuestions(),laws=lawStats(qs,state.includeAnnulled),articleCount=laws.reduce((n,l)=>n+l.articles.size,0),questionSet=new Set(laws.flatMap(l=>[...l.questions.keys()])),unconfirmed=new Set(laws.flatMap(l=>[...l.unconfirmed.keys()]));statsHTML([[laws.length,'leis / bases identificadas'],[articleCount,'artigos-base identificados'],[questionSet.size,'questões distintas'],[unconfirmed.size,'com artigo ou faixa a conferir']]);const exams=currentExams();$('#resultCount').textContent=`${laws.length} bases normativas · ordenadas por questões distintas`;$('#results').innerHTML=`<div class="assessment-notice"><strong>Incidência no conjunto enviado</strong><p>Uma questão conta uma vez por lei. Pode haver mais de uma lei ou artigo na mesma questão. As faixas temáticas não são desmembradas como se cada artigo tivesse sido cobrado. Clique na lei para ver artigos e questões; artigos estaduais não confirmados ficam identificados.</p></div><div class="law-table-wrap"><table class="law-table"><thead><tr><th>Lei / base normativa</th><th>Total</th>${exams.map(e=>`<th>${esc(e.id)}<small>${esc(e.board)}</small></th>`).join('')}<th>Artigos identificados</th></tr></thead><tbody>${laws.map(l=>`<tr><th><button class="law-open" data-law="${esc(l.law)}">${esc(l.law)} ↗</button>${l.unconfirmed.size?`<small>${l.unconfirmed.size} questão(ões) com artigo a conferir</small>`:''}</th><td><strong>${l.questions.size}</strong></td>${exams.map(e=>`<td>${[...l.questions.values()].filter(q=>q.examId===e.id).length||'—'}</td>`).join('')}<td>${l.articles.size?[...l.articles.entries()].sort((a,b)=>b[1].size-a[1].size).slice(0,4).map(([a,v])=>`<span class="article-count">Art. ${esc(a)} <b>${v.size}</b></span>`).join(''):'<span class="muted">Artigo a conferir</span>'}${l.articles.size>4?`<small>+ ${l.articles.size-4} artigos</small>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function openLaw(law){const l=lawStats(selectedQuestions(),state.includeAnnulled).find(l=>l.law===law);if(!l)return;modal(law,`<p>${l.questions.size} questões distintas nos filtros atuais. Referências por artigo podem se sobrepor.</p><div class="article-incidence">${[...l.articles.entries()].sort((a,b)=>b[1].size-a[1].size).map(([a,qs])=>`<article><strong>Art. ${esc(a)} <span>${qs.size} questão(ões)</span></strong><div>${[...qs.values()].map(questionChip).join('')}</div></article>`).join('')}</div>${l.unconfirmed.size?`<div class="info-panel"><strong>Artigo exato a conferir / referência temática</strong><p>Estas questões entram na incidência da lei, mas não são atribuídas artificialmente a cada artigo de uma faixa.</p>${[...l.unconfirmed.values()].map(questionChip).join('')}${l.thematic.map(t=>`<p>${esc(t.q.id)}: ${esc(t.articles.join(', '))} — faixa temática.</p>`).join('')}</div>`:''}<h3>Todas as questões desta lei</h3><div>${[...l.questions.values()].map(questionChip).join('')}</div>`)}
const transferLabels={'same-rule':'Mesma regra: base nacional basta','national-enough':'Lei nacional já permite acertar','same-base-details':'Mesma base + diferenças locais','state-specific':'Hipótese estadual adicional','national-indicated':'Aproveitamento nacional indicado',pending:'Aproveitamento a conferir','other-source':'Conhecimento técnico adicional',annulled:'Anulada'};
function transferInfo(q){return q.transferAssessment||{status:'pending',nationalEnough:'pending',statePresence:'pending',confirmed:false,base:'Base nacional a conferir.',difference:'Diferença ainda não identificada.',differenceTypes:[],postEdital:'Conferir antes de estimar estudo adicional.'}}
function nationalEnoughLabel(q){return {yes:'Sim — regra nacional suficiente',no:'Não — falta detalhe estadual',indicated:'Indicado pela análise inicial; confirmar',pending:'Ainda não confirmado','not-applicable':'Não aplicável'}[transferInfo(q).nationalEnough]||'Ainda não confirmado'}
function statePresenceLabel(q){const v=transferInfo(q);return v.statePresence==='confirmed'?'Sim — regra localizada em fonte estadual':v.statePresence==='not-applicable'?'Não exigida para o núcleo desta questão':'Confirmação estadual pendente';}
const studyTrackLabels={'state-complement':'Aprender na lei estadual','national-review':'Revisar a base que já resolve','national-addition':'Completar outra norma nacional',technical:'Estudar a técnica de auditoria','source-pending':'Confirmar antes de concluir',annulled:'Questão anulada'};
function studyGuide(q){return q.postEditalGuide||{baseExplanation:transferInfo(q).base,stateExplanation:transferInfo(q).difference,studyActions:[transferInfo(q).postEdital],example:'Exemplo ainda não detalhado.',focusLabel:q.topic,studyTrack:q.answer==='Anulada'?'annulled':transferInfo(q).nationalEnough==='yes'?'national-review':'state-complement'};}
function studyActionHTML(q){return `<ul class="study-actions">${studyGuide(q).studyActions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`;}
function studyCard(q){const g=studyGuide(q),exam=data().exams.find(e=>e.id===q.examId);return `<article class="study-card" data-study-q="${esc(q.id)}"><header><div><span class="study-track ${esc(g.studyTrack)}">${esc(studyTrackLabels[g.studyTrack])}</span><h4>${esc(g.focusLabel)}</h4></div><div>${questionChip(q)}<small>${esc(exam?.name||q.examId)} · ${esc(exam?.board||'')}</small></div></header>${g.studyTrack==='source-pending'?'<p class="study-pending-note">A regra foi identificada, mas a confirmação em fonte oficial permanece pendente. O exemplo não encerra essa conferência.</p>':''}<div class="study-card-grid"><section class="study-base"><h5>O que você já leva da base</h5><p>${esc(g.baseExplanation)}</p></section><section class="study-local"><h5>${g.studyTrack==='national-review'?'O estado acrescenta algo indispensável?':g.studyTrack==='national-addition'?'Qual norma geral ainda falta?':'O que aprender para esta cobrança'}</h5><p>${esc(g.stateExplanation)}</p></section></div><section class="study-do"><h5>Seu foco de estudo</h5>${studyActionHTML(q)}</section><div class="study-example"><strong>Exemplo para entender</strong><p>${esc(g.example)}</p></div><button class="evidence-open" data-q="${esc(q.id)}">Abrir questão, artigos e fontes ↗</button></article>`;}
function studyPlanHTML(qs){if(!qs.length)return '<div class="empty"><h3>Nenhuma questão com este foco e estes filtros.</h3></div>';const topics=new Map();for(const q of qs){if(!topics.has(q.topic))topics.set(q.topic,[]);topics.get(q.topic).push(q);}return `<div class="study-plan">${[...topics].map(([topic,items])=>`<section class="study-topic"><div class="study-topic-heading"><div><small>${items.length} questão(ões) · exemplos dos cadernos enviados</small><h3>${esc(topic)}</h3></div><span>${items.filter(q=>studyGuide(q).studyTrack==='state-complement').length} com foco estadual</span></div>${items.map(studyCard).join('')}</section>`).join('')}</div>`;}
function transferPanel(q){if(q.area!=='LTE')return '';const v=transferInfo(q),g=studyGuide(q);return `<section class="transfer-panel"><h3>Seu foco no pós-edital</h3><span class="study-track ${esc(g.studyTrack)}">${esc(studyTrackLabels[g.studyTrack])}</span><h4>${esc(g.focusLabel)}</h4><div class="study-base"><h5>A base que você já aproveita, explicada</h5><p>${esc(g.baseExplanation)}</p></div><div class="study-local"><h5>${g.studyTrack==='national-addition'?'O que falta completar na base nacional':g.studyTrack==='national-review'?'É preciso acrescentar regra estadual?':'O que a lei estadual acrescenta nesta questão'}</h5><p>${esc(g.stateExplanation)}</p></div><h5>O que estudar e comparar</h5>${studyActionHTML(q)}<div class="study-example"><strong>Exemplo para entender</strong><p>${esc(g.example)}</p></div><details class="study-proof"><summary>Conferência da base e da fonte estadual</summary><dl><dt>Só a lei nacional permitiria acertar?</dt><dd>${esc(nationalEnoughLabel(q))}</dd><dt>Esta regra foi localizada na lei estadual?</dt><dd>${esc(statePresenceLabel(q))}</dd><dt>Referências da análise anterior</dt><dd>${esc(g.baseReference||v.base)}</dd><dt>Tipo de diferença</dt><dd>${v.differenceTypes.map(t=>`<span class="detail-type">${esc(t)}</span>`).join(' ')||'A conferir'}</dd></dl></details><small>Os exemplos explicam as regras cobradas nestes cadernos. Ao estudar outro estado, compare os mesmos pontos na legislação do edital.</small></section>`;}

function transferMetrics(qs){return {national:qs.filter(q=>transferInfo(q).nationalEnough==='yes').length,details:qs.filter(q=>transferInfo(q).status==='same-base-details').length,specific:qs.filter(q=>transferInfo(q).status==='state-specific').length,pending:qs.filter(q=>['pending','national-indicated'].includes(transferInfo(q).status)).length}}
function renderPostEdital(){renderNav();const all=selectedQuestions().filter(q=>q.area==='LTE'),m=transferMetrics(all),rows=all.filter(q=>(!state.transfer||transferInfo(q).status===state.transfer)&&(!state.studyTrack||studyGuide(q).studyTrack===state.studyTrack)).sort((a,b)=>a.topic.localeCompare(b.topic,'pt-BR')||a.examId.localeCompare(b.examId)||a.number-b.number);statsHTML([[m.details+m.specific,'questões com complemento estadual'],[m.national,'questões resolvidas pela norma nacional'],[all.filter(q=>studyGuide(q).studyTrack==='national-addition').length,'questões sobre outra norma nacional'],[m.pending,'fontes específicas a confirmar']]);$('#resultCount').textContent=`${rows.length} questões LTE · roteiro de estudo com exemplos`;$('#results').innerHTML=`<div class="assessment-notice"><strong>Quando o edital sair, o que você precisa estudar?</strong><p>Comece por <b>Aprender na lei estadual</b>. Cada questão explica a regra geral que você já leva pronta e a informação local que deve comparar, memorizar ou praticar. Os exemplos mostram como a diferença decide a resposta.</p><p><b>Outra norma nacional</b> é um bloco que pode ser estudado antes do edital. <b>Revisar a base que já resolve</b> indica que não houve complemento estadual indispensável para aquela resposta. Os artigos e as fontes continuam disponíveis ao abrir a questão.</p><p>Os exemplos seguem a regra cobrada na prova indicada. Para o estado do seu edital, confira os mesmos pontos e a redação exigida.</p></div><nav class="study-focus-filters" aria-label="Escolher foco do pós-edital">${[['','Todos os focos'],...Object.entries(studyTrackLabels)].map(([value,label])=>`<button class="${state.studyTrack===value?'active':''}" data-study-track="${esc(value)}">${esc(label)} <b>${value?all.filter(q=>studyGuide(q).studyTrack===value).length:all.length}</b></button>`).join('')}</nav><p class="study-reading-key"><span>Azul: base já reaproveitável</span><span>Âmbar: informação a acrescentar</span><span>Exemplo: aplicação da diferença</span></p>${studyPlanHTML(rows)}${all.length?`<details class="study-audit-detail"><summary>Ver números da revisão e conferência documental</summary>${lteAuditHTML(rows)}</details>`:'<div class="empty">Selecione LTE ou Todas nas matérias para ver o aproveitamento.</div>'}`;}

$('#transferStatus').onchange=e=>{state.transfer=e.target.value;state.studyTrack='';render()};
$('#results').addEventListener('click',e=>{const b=e.target.closest('[data-study-track]');if(b){state.studyTrack=b.dataset.studyTrack;state.transfer='';$('#transferStatus').value='';render();}});
const qualityLabels={covered:'Regra localizada no resumo',omission:'Omissão dentro da lei-base',state:'Complemento estadual confirmado','other-national':'Outra lei nacional',other:'Jurisprudência / outra fonte','outside-summary':'Resumo desse bloco não enviado',pending:'Comparação pendente',annulled:'Anulada'};
function qualityInfo(q){return q.qualityAssessment||{status:'pending',confirmed:false,reason:'Questão ainda não confrontada com o resumo e a lei-base.',nationalLaw:'pending',summaryScope:'pending'}}
function qualityTag(q){const v=qualityInfo(q);return `<span class="quality-tag ${esc(v.status)}">${esc(qualityLabels[v.status]||qualityLabels.pending)}</span>`}
function qualityMetrics(qs){const counts=Object.fromEntries(Object.keys(qualityLabels).map(k=>[k,0]));for(const q of qs)counts[qualityInfo(q).status]++;return {...counts,confirmed:qs.filter(q=>qualityInfo(q).confirmed).length,valid:qs.filter(q=>qualityInfo(q).status!=='annulled').length}}
function lawBaseHTML(area){const bases=base.qualityMethod?.bases?.[area]||[];return `<div class="law-base"><strong>Lei-base para avaliar o resumo</strong><ul>${bases.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>${area==='Direito Tributário'?'<small>Correção de referência: os arquivos enviados são da LC 236/2026 (CTN). A LC 226/2026 trata de pagamentos retroativos a servidores; não foi incluída como alteração do CTN.</small>':''}<small>Usar a redação pertinente à prova. Constituição, jurisprudência e leis adicionais são registradas separadamente quando exigidas.</small></div>`}
function nationalQualityLabel(q){const v=qualityInfo(q);return ({present:'Sim — regra no texto nacional enviado','present-other-national-law':'Sim — em outra lei nacional','base-alone-insufficient':'Lei-base sozinha insuficiente; complemento estadual localizado','rule-covered-in-summary':'Regra geral já coberta pelo resumo','other-source-needed':'Conferir jurisprudência / conceito adicional','national-reference-identified':'Fonte nacional identificada; resumo correspondente não enviado','not-applicable':'Não aplicável',pending:'Ainda não confirmado'})[v.nationalLaw]||'Ainda não confirmado'}
function qualityAreaHTML(area,qs){const m=qualityMetrics(qs),rows=qs.filter(q=>!state.quality||qualityInfo(q).status===state.quality).sort((a,b)=>a.topic.localeCompare(b.topic,'pt-BR')||a.examId.localeCompare(b.examId)||a.number-b.number);return `<article class="quality-area"><h3>${esc(area)}</h3>${lawBaseHTML(area)}<div class="quality-summary"><span><b>${m.covered}</b> regras no resumo</span><span class="omission"><b>${m.omission}</b> omissões na lei-base</span><span><b>${m.state}</b> complementos estaduais confirmados</span><span><b>${m.pending}</b> comparações pendentes</span></div><p class="quality-conclusion">${m.omission?`Há ${m.omission} lacuna(s) identificada(s) dentro do escopo do resumo. `:''}${m.state?`${m.state} questão(ões) exigem regra estadual confirmada, que não deve ser contada como omissão do resumo nacional. `:''}${m.pending?'Ainda não há auditoria completa para atribuir uma nota de qualidade a este bloco.':'O resultado é restrito às questões selecionadas e não certifica cobertura de toda a lei.'}</p><div class="coverage-table-wrap"><table class="coverage-table quality-table"><thead><tr><th>Conteúdo / questão</th><th>Está no resumo?</th><th>Está na lei nacional?</th><th>Conclusão sobre o material</th><th>Fonte / o que falta</th></tr></thead><tbody>${rows.map(q=>{const v=qualityInfo(q),c=coverageInfo(q);return `<tr><th><small>${esc(q.topic)}</small>${questionChip(q)}</th><td>${c.status==='sufficient'?(c.resolutionRoute==='elimination'?'Sim, por eliminação documentada':'Sim, regra ou aplicação decisiva localizada'):c.status==='partial'?'Parcial: falta um elemento':c.status==='annulled'?'Anulada':'Regra não localizada no conjunto enviado'}</td><td>${esc(nationalQualityLabel(q))}</td><td>${qualityTag(q)}<small>${v.confirmed?'Conferência específica registrada':v.status==='covered'?'Baseado na análise de cobertura existente; sem nova auditoria integral':'Não é conclusão definitiva de falha ou de origem estadual'}</small></td><td><p>${esc(v.reason)}</p>${v.status==='omission'?refsHTML(q):''}${(c.lawEvidence||[]).map(ev=>`<small>${esc(materialById(ev.materialId)?.title||'Lei enviada')} · p. ${ev.page}</small>`).join('')}${(c.verifiedSources||[]).map(src=>`<a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(src.title)} · ${esc(src.articles)} ↗</a>`).join('')}<button class="evidence-open" data-q="${esc(q.id)}">Ver trechos e análise ↗</button></td></tr>`}).join('')}</tbody></table></div></article>`}
function renderQuality(){renderNav();const all=selectedQuestions(),m=qualityMetrics(all),areas=[...new Set(all.map(q=>q.area))];statsHTML([[m.omission,'omissões dentro da lei-base'],[m.state,'complementos estaduais confirmados'],[m['other-national']+m.other+m['outside-summary'],'outras fontes / escopos'],[m.pending,'comparações ainda pendentes']]);$('#resultCount').textContent=`${all.length} questões no recorte · ${m.confirmed} conclusões com conferência específica`;$('#results').innerHTML=`<div class="assessment-notice"><strong>Qualidade do resumo ≠ cobertura da prova</strong><p>Uma omissão só é atribuída ao resumo se a regra está na lei-base e pertence ao escopo dele. Regra estadual, outra lei nacional e ausência de um resumo inteiro são situações distintas. Não presumir origem estadual por não encontrar algo no resumo ou na lei-base.</p><p>Os percentuais da aba Cobertura medem questões respondíveis. Esta aba avalia a origem das lacunas; não calcula nota geral enquanto a conferência estiver incompleta.</p></div>${areas.map(a=>qualityAreaHTML(a,all.filter(q=>q.area===a))).join('')||'<div class="empty">Nenhuma questão neste recorte.</div>'}`}
$('#qualityStatus').onchange=e=>{state.quality=e.target.value;render()};
function sourceCheck(q){const c=coverageInfo(q);if(q.area==='LTE'&&q.lteReview){const v=transferInfo(q),reviewed=q.lteReview.sourceStatus==='confirmed',quality=qualityInfo(q);return {reviewed,summary:c.status==='sufficient'?(c.resolutionRoute==='elimination'?'Resposta sustentada por eliminação':'Regra decisiva ou aplicação suficiente'):c.status==='partial'?'Base localizada; falta complemento':c.status==='annulled'?'Anulada':'Regra não localizada nos resumos',national:nationalEnoughLabel(q),state:v.statePresence==='confirmed'?(v.nationalEnough==='yes'?'Regra estadual confirmada; sem complemento decisivo para esta resposta':'Complemento estadual confirmado'):v.statePresence==='not-applicable'?'Regra estadual não exigida para o núcleo': 'Confirmação do texto estadual pendente',location:(c.lawEvidence||[]).map(ev=>`${materialById(ev.materialId)?.title||'Lei enviada'}, p. ${ev.page}`).concat((c.verifiedSources||[]).map(v=>`${v.title}: ${v.articles}`)).join(' · ')||q.lteReview.reason};}if(q.ingestionBatch&&q.area!=='LTE'){const quality=qualityInfo(q);return {reviewed:true,summary:coverageLabel(q),national:quality.status==='covered'?'Regra nacional localizada no resumo':quality.status==='outside-summary'?'Norma nacional fora do recorte dos resumos fornecidos':quality.status==='omission'?'Regra na lei-base; lacuna do resumo identificada':quality.status==='annulled'?'Questão anulada; fora dos índices':'Complemento nacional ou jurisprudencial identificado no detalhe',state:'Legislação estadual não é o complemento desta cobrança nacional.',location:(q.lawRefs||[]).map(r=>r.law+' '+(r.articles||[]).join(', ')).join(' · ')}}const reviewed=!!c.reviewAudit;return {reviewed,summary:c.status==='sufficient'?'Regra decisiva localizada':c.status==='partial'?'Base localizada; falta complemento':c.status==='notfound'?'Regra não localizada nos resumos':c.status==='annulled'?'Anulada':'Cobertura a conferir',national:reviewed?(c.status==='sufficient'?'Base geral suficiente para esta resposta':'A base geral não substitui o detalhe estadual identificado'):'Conferência específica da regra faltante na lei nacional pendente',state:reviewed?(c.complementType==='state'?'Complemento estadual confirmado':'Sem complemento estadual necessário para esta resposta'):'Origem estadual ainda não confirmada por conferência documental',location:reviewed?(c.lawEvidence||[]).map(ev=>`${materialById(ev.materialId)?.title||'Lei enviada'}, p. ${ev.page}`).concat((c.verifiedSources||[]).map(v=>`${v.title}: ${v.articles}`)).join(' · '):'Referências e evidências iniciais no detalhe; ainda não certificam a origem da lacuna.'}}
function sourceCheckHTML(q){const v=sourceCheck(q);return `<section class="source-check"><h3>Onde está a regra necessária?</h3><dl><dt>Resumo</dt><dd>${esc(v.summary)}</dd><dt>Lei nacional × estadual</dt><dd>${esc(nationalQualityLabel(q))}</dd><dt>Qualidade do resumo</dt><dd>${qualityTag(q)}<p>${esc(qualityInfo(q).reason)}</p></dd><dt>Legislação estadual</dt><dd>${esc(v.state)}</dd><dt>Fonte da confirmação</dt><dd>${esc(v.location)}</dd></dl><small>${v.reviewed?'Conferência individual registrada para esta questão.':'O selo de estudo é uma classificação inicial. Não afirmar ausência na lei nacional por falta de resultado em busca.'}</small></section>`}
function reportMetrics(qs){const counts=coverageCounts(qs),valid=qs.length-counts.annulled,partial=partialBreakdown(qs);return {counts,partial,valid,pct:valid?(counts.sufficient/valid*100).toFixed(1).replace('.',',')+'%':'—',verified:qs.filter(q=>coverageInfo(q).reviewAudit).length,stateVerified:qs.filter(q=>coverageInfo(q).reviewAudit&&coverageInfo(q).complementType==='state').length}}
function examReportRows(qs){return currentExams().map(exam=>{const questions=qs.filter(q=>q.examId===exam.id);return {exam,questions,...reportMetrics(questions)}}).filter(r=>r.questions.length)}
function reportAreaHTML(area,qs){const m=reportMetrics(qs),rows=examReportRows(qs),topics=contentCoverage(qs),common=topics.filter(g=>new Set(g.questions.map(q=>q.examId)).size>1).sort((a,b)=>new Set(b.questions.map(q=>q.examId)).size-new Set(a.questions.map(q=>q.examId)).size||b.questions.length-a.questions.length),gaps=topics.filter(g=>g.counts.partial+g.counts.notfound+g.counts.pending>0).sort((a,b)=>(b.valid-b.counts.sufficient)-(a.valid-a.counts.sufficient));const guidance={ 'Direito Tributário':'A lei-base é o CTN, com as alterações da LC 236/2026 no recorte pertinente. Constituição e jurisprudência aparecem como fontes adicionais quando exigidas.',Reforma:'Comparar EC 132/2023, LC 214/2025 e LC 227/2026, na redação vigente no corte do edital. Resumos atualizados depois da prova não demonstram o que já estava disponível na época.',LTE:'Separar a base nacional de ICMS, IPVA e ITCMD das regras estaduais. Uma questão de LTE pode ser resolvida pela base geral; o nome da disciplina não determina sua origem.'}[area]||'A comparação usa as questões e os materiais catalogados nesta matéria.';return `<article class="subject-report"><div class="report-heading"><div><small>${esc(state.subject)}</small><h3>${esc(area)}</h3></div><strong>${m.pct}<small>questões respondíveis</small></strong></div><p>${esc(guidance)}</p>${dtAuditHTML(qs)}${lteAuditHTML(qs)}<div class="report-answer"><strong>Só com os resumos, daria para responder todas?</strong><p>${m.valid===0?'Não há questões válidas neste recorte.':m.counts.sufficient===m.valid?`A análise atual encontrou suporte para todas as ${m.valid} questões válidas.`:`Não. A análise atual sustenta ${m.counts.sufficient} de ${m.valid} questões válidas (${m.pct}). As outras ${m.valid-m.counts.sufficient} exigem complemento ou conferência.`} ${m.counts.annulled} anulada(s) excluída(s). Isso mede cobertura do material, não o desempenho pessoal.</p></div><div class="report-metrics"><span><b>${m.partial.state}</b> L + estadual <small>${m.stateVerified} com fonte estadual confirmada nesta revisão</small></span><span><b>${m.partial.national}</b> L + base nacional</span><span><b>${m.counts.notfound}</b> Não localizadas no resumo <small>não equivale a ausência na lei nacional</small></span><span><b>${m.verified}/${qs.length}</b> com conferência documental recente</span></div><h4>Comparativo das provas e bancas</h4><div class="coverage-table-wrap"><table class="coverage-table report-exams"><thead><tr><th>Prova / banca</th><th>Válidas</th><th>Só resumo · L</th><th>Cobertura</th><th>L + estadual</th><th>L + nacional</th><th>Não localizada</th><th>Questões</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${esc(r.exam.name)}<small>${esc(r.exam.board)} · ${esc(r.exam.year)}</small></th><td>${r.valid}</td><td>${r.counts.sufficient}</td><td>${r.pct}</td><td>${r.partial.state}</td><td>${r.partial.national}</td><td>${r.counts.notfound}</td><td><details><summary>Ver questões</summary>${r.questions.map(questionChip).join(' ')}</details></td></tr>`).join('')}</tbody></table></div><p class="save-caption">Os percentuais descrevem os cadernos enviados. Provas com anos, assuntos e quantidades diferentes não isolam o efeito da banca e não permitem prever a próxima prova.</p><h4>Conteúdos semelhantes entre as provas</h4>${common.length?`<div class="report-topics">${common.slice(0,8).map(g=>`<div><b>${esc(g.topic)}</b><small>${new Set(g.questions.map(q=>q.examId)).size} provas · ${g.counts.sufficient}/${g.valid} com L</small><div>${g.questions.map(questionChip).join(' ')}</div></div>`).join('')}</div>`:'<p>Não há tema comum entre duas provas neste recorte.</p>'}${lawBaseHTML(area)}<h4>Qualidade do resumo neste recorte</h4><p>${qualityMetrics(qs).omission} omissão(ões) dentro da lei-base · ${qualityMetrics(qs).state} complemento(s) estadual(is) confirmado(s) · ${qualityMetrics(qs).pending} comparação(ões) pendente(s). Veja a aba Qualidade dos resumos para os fundamentos por questão.</p><h4>Onde concentrar a leitura complementar</h4>${gaps.length?`<ol class="report-gaps">${gaps.slice(0,6).map(g=>`<li><strong>${esc(g.topic)}</strong>: ${g.valid-g.counts.sufficient} de ${g.valid} questões sem cobertura integral. ${g.counts.partial} parciais; ${g.counts.notfound} não localizadas.</li>`).join('')}</ol>`:'<p>Nenhuma lacuna identificada neste recorte.</p>'}<details class="report-detail"><summary>Relatório completo por conteúdo</summary>${contentCoverageHTML(qs)}</details><details class="report-detail"><summary>Resumo × lei nacional × legislação estadual: conferir cada questão</summary><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Questão / conteúdo</th><th>Resumo</th><th>Lei nacional</th><th>Complemento estadual</th></tr></thead><tbody>${qs.map(q=>{const v=sourceCheck(q);return `<tr><th>${questionChip(q)}<small>${esc(q.topic)}</small></th><td>${esc(v.summary)}</td><td>${esc(v.national)}</td><td>${esc(v.state)}<small>${esc(v.location)}</small></td></tr>`}).join('')}</tbody></table></div></details></article>`}
function taxRenderReports(){renderNav();const all=selectedQuestions(),m=reportMetrics(all),areas=[...new Set(all.map(q=>q.area))];statsHTML([[m.counts.sufficient,'questões com L integral'],[m.pct,'cobertura no recorte válido'],[m.verified,'conferências documentais recentes'],[areas.length,'relatórios por matéria']]);$('#resultCount').textContent=`${areas.length} matérias · ${all.length} questões nos filtros atuais`;$('#results').innerHTML=`<div class="assessment-notice"><strong>Comparar materiais e provas para decidir o que estudar</strong><p>O relatório distingue cobertura do resumo, complemento nacional e estadual. As conferências registradas têm fonte individual. Nas demais questões, a classificação existente não prova que o conteúdo falte na lei nacional; essa verificação permanece indicada como pendente. Nenhum resultado de busca negativo vira automaticamente regra estadual.</p></div>${areas.length?areas.map(a=>reportAreaHTML(a,all.filter(q=>q.area===a))).join(''):'<div class="empty">Nenhuma questão neste recorte.</div>'}`}
$('#programObjective').addEventListener('click',()=>modal('OBJETIVO DO PROGRAMA',`<div class="objective-copy"><p><strong>Outras matérias:</strong> provas nas colunas, assuntos semelhantes na mesma linha, número e cobrança por questão. Em Contabilidade, distinguir exercício/cálculo, teoria e mista, com quantidade e percentual por banca. Os cadernos enviados estão organizados por esses critérios. A cobertura do Concurseiro Fora da Caixa é conferida por questão, com páginas e trechos. Blocos sem resumo específico ficam separados de lacunas nos materiais enviados.</p><p><strong>Objetivo:</strong> nos blocos tributários, avaliar a fidelidade dos resumos à lei-base; em todas as matérias, mostrar quantas questões têm regra, conceito ou procedimento suficiente nos resumos enviados.</p><p><strong>Roteiro do pós-edital:</strong> explicar a base nacional em linguagem simples, detalhar o que aprender na lei estadual, indicar tarefas de comparação e mostrar exemplos por questão. O foco é orientar seu estudo quando o edital sair.</p><p><strong>Foco principal em LTE:</strong> mostrar se a regra nacional já permite acertar, mesmo quando também está na lei estadual; identificar a base reaproveitável e cada diferença concreta a estudar no pós-edital.</p><p><strong>O que faço:</strong> comparo questões e gabaritos com resumos, leis nacionais e legislação estadual; registro páginas, artigos e fontes e calculo a cobertura dos materiais por prova e banca.</p><p><strong>Objetivo da conferência técnica:</strong> identificar a regra decisiva e sua origem, separar base nacional de peculiaridade estadual e apontar exatamente o complemento de estudo, com evidência verificável.</p><p><strong>Qualidade:</strong> regra na lei-base e ausente no resumo, dentro do escopo = omissão do material. Regra estadual comprovada = complemento local. Outra norma nacional, jurisprudência ou resumo não enviado ficam separados. Não localizar não prova origem estadual.</p><p><strong>Critério:</strong> L = regra localizada; L + estadual = falta regra local; L + nacional = falta norma geral, jurisprudência ou conceito; não localizado = regra não encontrada no resumo. Fonte ainda não verificada fica expressamente pendente.</p><p>O programa avalia suficiência dos materiais. Não mede seu conhecimento nem garante acerto. A conferência considera o recorte temporal da prova.</p></div>`));
function renderMaterials(){renderOrganizedMaterials()}
function openMaterial(id){const m=materialById(id);if(!m)return;const questions=data().questions.filter(q=>(q.coverage?.summaryEvidence||[]).concat(q.coverage?.lawEvidence||[],q.summaryCoverage?.summaryEvidence||[]).some(ev=>ev.materialId===id));modal('Identificação do material',`<span class="material-type ${m.kind}">${esc(m.kind==='summary'?'Resumo · '+m.publisher:({law:'Texto de lei / compilação',update:'Atualização / trechos'}[m.kind]||'Material'))}</span><h3 class="${m.kind==='law'?'material-law-title':''}">${esc(m.title)}</h3><p>${esc(m.classificationReason||m.identification)}</p><p><b>Arquivo:</b> ${esc(m.filename)}<br><b>Páginas:</b> ${m.pageCount}</p>${m.duplicateOf?`<div class="info-panel">Texto idêntico a ${esc(materialById(m.duplicateOf)?.filename||m.duplicateOf)}. Não conta como conteúdo adicional.</div>`:''}<p>${questions.length} questão(ões) com evidência de leitura neste material. Isso não representa todas as questões que ele poderia cobrir.</p><div>${questions.map(questionChip).join('')}</div>`)}
function renderPendingSubject(){renderNav();const c=subjectCatalog(),rows=c.sourceQuestions.filter(q=>(!state.board||data().exams.find(e=>e.id===q.examId)?.board===state.board)&&(!state.exam||q.examId===state.exam)&&(!state.search||normalize(q.sourceTopicLabel+' '+q.number+' '+q.examId).includes(normalize(state.search)))),exams=data().exams.filter(e=>rows.some(q=>q.examId===e.id));statsHTML([[c.availableCount,'questões identificadas nos cadernos'],[0,'questões analisadas nesta matéria'],[exams.length,'provas disponíveis no filtro'],['Pendente','análise por conteúdo']]);$('#sectionTitle').textContent=c.name;$('#sectionSubtitle').textContent='Matéria criada · análise sumária aguardando execução';$('#areas').hidden=true;$('#resultCount').textContent=`${rows.length} questões disponíveis neste recorte · agrupamento comparativo ainda pendente`;$('#results').innerHTML=`<section class="subject-ready"><span class="catalog-pending">MATÉRIA CADASTRADA · AGUARDANDO ANÁLISE</span><h3>${esc(c.name)}</h3><p>Os cadernos já estão identificados. A próxima análise colocará <b>assuntos nas linhas e provas nas colunas</b>, com o número e uma síntese curta da cobrança de cada questão. Temas diferentes ficarão em linhas separadas.</p><p>Esta tela é um inventário dos arquivos enviados; os temas semelhantes entre provas ainda serão conferidos.</p><div class="catalog-method"><strong>${c.analysisMode==='accounting'?'Contabilidade: classificação adicional por banca':'Análise sumária combinada'}</strong>${c.analysisMode==='accounting'?`<ul><li><b>Exercício/cálculo:</b> apuração de valores, lançamentos ou resolução prática.</li><li><b>Teoria:</b> conceitos e regras sem executar procedimento contábil.</li><li><b>Mista:</b> partes teóricas e práticas efetivamente cobradas; sem duplicar a contagem.</li></ul><p>O relatório trará quantidade e percentual por banca, além dos assuntos e das questões. As classificações ainda não foram atribuídas.</p>`:'<p>Comparação por assunto, número das questões, detalhe breve do que apareceu e recorrência entre provas e bancas.</p>'}</div>${c.analysisMode==='accounting'?`<h4>Contabilidade por banca — preparação do relatório</h4><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Banca</th><th>Disponíveis</th><th>Exercício/cálculo</th><th>Teoria</th><th>Mista</th></tr></thead><tbody>${[...new Set(exams.map(e=>e.board))].map(board=>`<tr><th>${esc(board)}</th><td>${rows.filter(q=>data().exams.find(e=>e.id===q.examId)?.board===board).length}</td><td colspan="3">A classificar · percentuais ainda não calculados</td></tr>`).join('')}</tbody></table></div><p class="save-caption">Geral, Custos e os blocos de Contabilidade Pública identificados estão reunidos aqui. Classificar os tipos exige ler as questões.</p>`:''}<h4>Cadernos disponíveis</h4><div class="catalog-exams">${exams.map(e=>{const rs=rows.filter(q=>q.examId===e.id);return `<article><strong>${esc(e.name)} <span>${esc(e.board)} · ${e.year}</span></strong><b>${rs.length} questões</b><p>${esc(e.source)}</p><details><summary>Ver numeração identificada</summary><div>${rs.map(q=>`<a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer" title="Abrir questão no TEC">Q${q.number}</a>`).join(' ')}</div></details></article>`}).join('')||'<p>Nenhuma questão disponível com estes filtros.</p>'}</div></section>`;}
function render(){const c=subjectCatalog(),pending=!!c&&!data().questions.some(q=>q.subject===state.subject),tax=state.subject==='Tributário';document.querySelectorAll('[data-page]').forEach(b=>b.hidden=!tax&&!['map','reports','coverage','materials'].includes(b.dataset.page));$('.comparison-filters').hidden=!tax;$('.literalidade-key').hidden=!tax;if(pending){$('#coverageFilter').hidden=true;$('#annulledFilter').hidden=true;$('.view-toggle').hidden=true;$('#qualityControls').hidden=true;$('#transferControls').hidden=true;$('#common').closest('label').hidden=true;renderPendingSubject();return;}const titles={postEdital:['Aproveitamento no pós-edital · LTE','Lei nacional suficiente, regra repetida ou complemento estadual: o que você realmente precisa acrescentar.'],quality:['Qualidade dos resumos','Resumo × lei-base: identificar omissão, complemento estadual e outras fontes.'],reports:['Relatório por matéria','Comparativo das provas, cobertura dos resumos e origem das lacunas.'],map:['Mapa de conteúdos','Assuntos nas linhas. Provas nas colunas.'],coverage:['Cobertura dos resumos','Por conteúdo: quantas questões os resumos sustentam e onde falta complemento.'],laws:['Incidência por lei','Frequência no conjunto enviado, com artigos e questões.'],materials:['Seus materiais','Resumos, textos de lei e atualizações identificados pelo conteúdo.']};const title=titles[state.page]||titles.map;$('#sectionTitle').textContent=title[0];$('#sectionSubtitle').textContent=title[1];document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#coverageFilter').hidden=!tax||state.page!=='coverage';$('#annulledFilter').hidden=state.page!=='laws';$('.view-toggle').hidden=state.page!=='map';$('#common').closest('label').hidden=state.page==='materials';$('#areas').hidden=state.page==='materials';$('#qualityControls').hidden=state.page!=='quality';$('#transferControls').hidden=state.page!=='postEdital';if(state.page==='postEdital')renderPostEdital();else if(state.page==='quality')renderQuality();else if(state.page==='reports')renderReports();else if(state.page==='coverage'){if(tax)renderCoverage();else renderCFCCoverage()}else if(state.page==='laws')renderLaws();else if(state.page==='materials'){if(tax)renderMaterials();else renderCFCMaterials()}else renderMap()}
$('#pageTabs').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){state.page=b.dataset.page;if(state.page==='postEdital')state.area='LTE';render()}});$('#coverageStatus').onchange=e=>{state.coverage=e.target.value;render()};$('#includeAnnulled').onchange=e=>{state.includeAnnulled=e.target.checked;render()};$('#modalContent').addEventListener('click',e=>{const b=e.target.closest('[data-q]');if(b){$('#modal').close();openQuestion(b.dataset.q)}});


function lteAuditHTML(qs){const lte=qs.filter(q=>q.area==='LTE'&&q.lteReview);if(!lte.length)return '';const c=coverageCounts(lte),valid=lte.length-c.annulled,verified=lte.filter(q=>q.lteReview.sourceStatus==='confirmed').length,pending=lte.filter(q=>q.lteReview.sourceStatus==='pending'),m=qualityMetrics(lte),n=lte.filter(q=>transferInfo(q).nationalEnough==='yes').length;return `<section class="dt-audit lte-audit"><h3>LTE — revisão por questão e fonte</h3><p><strong>${c.sufficient} de ${valid} questões válidas respondíveis com os resumos (${valid?(c.sufficient/valid*100).toFixed(1).replace('.',','):'0'}%).</strong> ${c.partial} exigem complemento; ${c.notfound} regras não foram localizadas nos resumos. ${c.annulled} anuladas fora do índice.</p><p><b>Qualidade do material:</b> ${m.state} complementos estaduais confirmados; ${m['outside-summary']} questões de blocos nacionais sem resumo próprio enviado; ${m['other-national']} fonte(s) nacional(is) adicional(is); ${m.other} questão(ões) de outra fonte técnica. Ausência de resumo de Simples, NF-e ou EFD não é uma omissão da Kandir.</p><p><b>Conhecendo a norma nacional:</b> ela permite a resposta em ${n} questões, inclusive normas adicionais à Kandir. Isso é diferente de estudar só os resumos. ${verified}/${valid} questões válidas têm conclusão documental registrada. ${pending.length?`Faltam confirmar estes textos específicos: ${pending.map(questionChip).join(' ')}.`:'Nenhuma confirmação específica pendente neste recorte.'}</p><p>O L pode resultar de aplicação ou eliminação, com a rota explícita. A SP-155, quando selecionada, não certifica a presunção estadual no resumo: certifica a exclusão das quatro alternativas incorretas. Os materiais posteriores à prova são avaliados retrospectivamente.</p><details><summary>Ver o fundamento de cada questão LTE</summary><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Questão / cobrança</th><th>Resumo / rota</th><th>Norma nacional / diferença estadual</th><th>Fonte</th></tr></thead><tbody>${lte.map(q=>`<tr><th>${questionChip(q)}<small>${esc(q.topic)}</small></th><td>${coverageMini(q)}<p>${esc(q.coverage.reason)}</p>${resolutionPanel(q)}</td><td>${esc(transferInfo(q).base)}<p>${esc(transferInfo(q).difference)}</p></td><td>${esc(statePresenceLabel(q))}<button class="evidence-open" data-q="${esc(q.id)}">Ver artigos e fontes ↗</button></td></tr>`).join('')}</tbody></table></div></details></section>`;}

const accountingLabels={exercise:'Exercício/cálculo',theory:'Só teoria',mixed:'Mista'};
function accountingBadge(q){return q.accountingType?`<span class="accounting-badge ${esc(q.accountingType)}">${esc(accountingLabels[q.accountingType])}</span>`:''}
function card(q){if(q.subject==='Tributário')return taxCard(q);return `<button class="question-card ${accountingQuestionClass(q)}" data-q="${esc(q.id)}"><span class="qtop"><span class="qnum">Q${esc(q.number)}</span>${cfcBadge(q)}${accountingBadge(q)}${progress[q.id]&&progress[q.id]!=='Não estudada'?'<span class="qprogress">✓</span>':''}</span><p>${esc(q.summary)}</p>${answerBadge(q)}${q.classificationNote?'<small class="muted">Há observação sobre a extração</small>':''}</button>`}
function openQuestion(id){const q=data().questions.find(q=>q.id===id);if(!q||q.subject==='Tributário')return taxOpenQuestion(id);activeQuestion=id;const e=data().exams.find(e=>e.id===q.examId);$('#detailEyebrow').textContent=`${e?.name||q.examId} · ${e?.board||''} · ${e?.year||''}`;$('#detailContent').innerHTML=`<div class="detail-inner"><h2>Questão ${q.number}<br>${esc(q.topic)}</h2><div class="badges"><span class="badge">${esc(q.subject)}</span><span class="badge">${esc(q.area)}</span>${accountingBadge(q)}</div><p class="detail-summary">${esc(q.summary)}</p>${topicStudyLinks(q)}${q.accountingReason?`<section class="assessment-notice"><strong>Por que ${esc(accountingLabels[q.accountingType])}?</strong><p>${esc(q.accountingReason)}</p></section>`:''}${q.classificationNote?`<p class="assessment-notice">${esc(q.classificationNote)}</p>`:''}${cfcPanel(q)}<h3>Texto do caderno</h3>${answerPanel(q)}<div class="question-body">${questionBodyHTML(q)}</div><p class="save-caption">Fonte: ${esc(q.sourceFile||e?.source||'caderno enviado')} · página(s) ${esc((q.sourcePages||[]).join(', '))}. Numeração do TEC. Fórmulas, imagens e tabelas podem não aparecer integralmente no texto extraído; consulte o PDF para resolver.</p><a class="source-link" href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">Abrir questão no TEC ↗</a><div class="detail-divider"></div><h3>Seu acompanhamento</h3><div class="status-buttons">${['Não estudada','Estudada','Revisada'].map(s=>`<button data-status="${s}" class="${(progress[id]||'Não estudada')===s?'active':''}">${s}</button>`).join('')}</div><h3 style="margin-top:24px">Suas anotações</h3><textarea id="questionNotes" placeholder="Registre dúvidas e pontos para revisar…">${esc(notes[id]||'')}</textarea><p class="save-caption" id="noteCaption">Salvas automaticamente neste navegador. Use Exportar para guardar uma cópia.</p></div>`;$('#detail').showModal()}
function accountingCounts(qs){const valid=qs.filter(q=>!['Anulada','Desatualizada'].includes(q.answer));return {valid:valid.length,exercise:valid.filter(q=>q.accountingType==='exercise').length,theory:valid.filter(q=>q.accountingType==='theory').length,mixed:valid.filter(q=>q.accountingType==='mixed').length,excluded:qs.length-valid.length}}
function accountingTable(all){const boards=[...new Set(all.map(q=>data().exams.find(e=>e.id===q.examId)?.board))];const cell=(n,total)=>`${n} <small>${total?(100*n/total).toLocaleString('pt-BR',{maximumFractionDigits:1}):0}%</small>`;return `<h3>Contabilidade: exercícios ou teoria por banca</h3><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Banca / prova</th><th>Válidas</th><th>Exercício/cálculo</th><th>Teoria</th><th>Mista</th><th>Excluídas</th></tr></thead><tbody>${boards.map(b=>{const qs=all.filter(q=>data().exams.find(e=>e.id===q.examId)?.board===b),rows=[{label:b,qs},...data().exams.filter(e=>qs.some(q=>q.examId===e.id)).map(e=>({label:'↳ '+e.name,qs:qs.filter(q=>q.examId===e.id)}))];return rows.map(r=>{const c=accountingCounts(r.qs);return `<tr><th>${esc(r.label)}</th><td>${c.valid}</td><td>${cell(c.exercise,c.valid)}</td><td>${cell(c.theory,c.valid)}</td><td>${cell(c.mixed,c.valid)}</td><td>${c.excluded}</td></tr>`}).join('')}).join('')}</tbody></table></div><p class="save-caption">Exercício: executar cálculo, lançamento ou procedimento. Teoria: reconhecer conceitos/regras ou julgar afirmações. Mista: partes teóricas e práticas distintas. Aplicar uma regra em um cálculo não torna a questão mista. Anuladas/desatualizadas ficam fora dos percentuais; abra a questão para ver a justificativa.</p>`}
function renderReports(){if(state.subject==='Tributário')return taxRenderReports();renderNav();const all=selectedQuestions(),exams=currentExams(),topics=groups().list,valid=all.filter(q=>!['Anulada','Desatualizada'].includes(q.answer)),common=topics.filter(g=>new Set(g.questions.map(q=>q.examId)).size>=2);statsHTML([[all.length,'questões no recorte'],[topics.length,'assuntos identificados'],[common.length,'assuntos em duas ou mais provas'],[cfcMetrics(all).pct,'questões com base suficiente no CFC']]);$('#resultCount').textContent=`${state.subject} · ${all.length} questões · ${valid.length} válidas`;$('#results').innerHTML=portugueseIncidenceOverview()+`<section class="assessment-notice"><strong>Como as provas cobraram ${esc(state.subject)}</strong><p>Compare os assuntos recorrentes no quadro abaixo e abra as questões para ver a cobrança específica e o gabarito. As contagens se referem aos cadernos enviados, com numeração do TEC, e não a um levantamento de todas as provas da banca.</p><p>${exams.map(e=>`${esc(e.name)} (${esc(e.board)}): <b>${all.filter(q=>q.examId===e.id).length}</b>`).join(' · ')}</p><p>${common.length?`Os conteúdos presentes em mais provas são: <b>${common.slice().sort((a,b)=>new Set(b.questions.map(q=>q.examId)).size-new Set(a.questions.map(q=>q.examId)).size).slice(0,5).map(g=>esc(g.topic)).join('; ')}</b>.`:'Nenhum assunto deste recorte aparece em duas provas; amplie os filtros para comparar.'}</p></section>${state.subject==='Contabilidade'?accountingTheoryOverview(all)+accountingTable(all):''}${cfcSummaryHTML(all)}${cfcContentHTML(all)}<h3>Incidência por assunto e prova</h3><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Assunto</th>${exams.map(e=>`<th>${esc(e.name)}<small>${esc(e.board)}</small></th>`).join('')}<th>Total</th></tr></thead><tbody>${topics.map(g=>`<tr><th>${esc(g.topic)}<small>${esc(g.area)}</small></th>${exams.map(e=>`<td>${g.questions.filter(q=>q.examId===e.id).map(q=>`<button class="law-open" data-q="${esc(q.id)}" title="${esc(q.summary)}">Q${q.number}</button>`).join(' · ')||'—'}</td>`).join('')}<td>${g.questions.length}</td></tr>`).join('')}</tbody></table></div>`}

const cfcLabels={sufficient:'CFC · suficiente',partial:'CFC · parcial',notfound:'CFC · não localizado',notprovided:'Sem resumo específico',pending:'CFC · a conferir',annulled:'Anulada'};
function cfcInfo(q){return q.summaryCoverage||{status:'pending',reason:'Conferência ainda não registrada.',summaryEvidence:[]}}
function cfcBadge(q){if(q.subject==='Tributário')return '';const c=cfcInfo(q);return `<span class="cfc-seal ${esc(c.status)}" title="${esc(c.reason)}">${esc(cfcLabels[c.status]||'CFC · a conferir')}</span>`}
function cfcMetrics(qs){const counts={sufficient:0,partial:0,notfound:0,notprovided:0,pending:0,annulled:0};for(const q of qs){const c=cfcInfo(q);counts[c.status in counts?c.status:'pending']++;}const valid=qs.length-counts.annulled;return {...counts,total:qs.length,valid,pct:valid?(100*counts.sufficient/valid).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':'—',outside:qs.filter(q=>['no-subject-summary','outside-declared'].includes(cfcInfo(q).scope)&&cfcInfo(q).status!=='annulled').length}}
function cfcNotice(){return `<section class="assessment-notice cfc-notice"><strong>Concurseiro Fora da Caixa · conferência dos 15 PDFs enviados</strong><p><b>Suficiente:</b> regra, conceito ou procedimento necessário localizado no resumo, inclusive por aplicação ou eliminação. <b>Parcial:</b> há base útil, mas falta conhecimento decisivo. <b>Não localizado:</b> a base necessária não foi encontrada na busca contextual dos materiais indicados. <b>Sem resumo específico:</b> a disciplina ou bloco não foi fornecido; isso não é falha imputável a outro resumo.</p><p>Os percentuais contam apenas as suficientes como respondíveis com a base do resumo; parciais não recebem meio acerto. Anuladas ficam fora do denominador. Esta é uma avaliação da suficiência do material, sem medir seu desempenho pessoal. Versões “15.09” não identificam o ano; a comparação é retrospectiva.</p></section>`}
function cfcPanel(q){const c=cfcInfo(q),scope={within:'Conteúdo dentro do recorte do resumo', 'outside-declared':'Cobrança fora do recorte declarado do resumo', 'no-subject-summary':'Bloco sem resumo específico enviado', 'cross-subject':'Base encontrada em outra disciplina'};return `<section class="coverage-panel cfc-panel"><div class="comparison-title"><h3>Só com o Concurseiro Fora da Caixa?</h3>${cfcBadge(q)}</div><p>${esc(c.reason)}</p><p><b>O que a questão exige:</b> ${esc(c.neededKnowledge||q.summary)}</p>${c.missingKnowledge?`<div class="cfc-gap"><strong>O que complementar</strong><p>${esc(c.missingKnowledge)}</p></div>`:''}<p class="save-caption">${esc(scope[c.scope]||'Recorte dos arquivos enviados')} · ${esc({application:'Aplicação da regra/procedimento',elimination:'Resolução por eliminação',enunciado:'Base do resumo + dados do enunciado',incomplete:'Base parcial, sem rota completa',none:'Sem base suficiente localizada'}[c.resolutionRoute]||'Rota a conferir')}</p>${(c.summaryEvidence||[]).map(ev=>evidenceHTML(ev,'summary')).join('')}${c.notes?`<p class="temporal-note">${esc(c.notes)}</p>`:''}<details class="cfc-search"><summary>Escopo da conferência</summary><p>Materiais consultados: ${(c.searchedMaterialIds||[]).map(id=>esc(materialById(id)?.title||id)).join('; ')||'Não há resumo específico desse bloco nos arquivos enviados.'}</p><p>Termos de busca: ${esc((c.searchTerms||[]).join(', '))||'Não se aplica à ausência de envio de material.'}</p><p>Não localizar é uma conclusão limitada aos arquivos e às buscas indicadas. Não prova que o conteúdo não exista em outro material ou versão.</p></details></section>`}
function cfcSummaryHTML(qs){const m=cfcMetrics(qs);let conclusion=m.valid&&m.sufficient===m.valid?'Sim: foi localizada base suficiente para todas as questões válidas deste recorte.':m.valid?`Não foi confirmada cobertura integral: ${m.sufficient} de ${m.valid} questões válidas têm base suficiente localizada (${m.pct}).`:'Não há questão válida neste recorte.';return `${cfcNotice()}<section class="assessment-notice"><strong>Só com os resumos, daria para responder todas?</strong><p>${esc(conclusion)} São ${m.partial} parciais, ${m.notfound} não localizadas, ${m.notprovided} sem resumo específico e ${m.pending} pendentes. ${m.annulled} anuladas fora do índice.</p><p><b>Qualidade do resumo:</b> ${m.outside} questões válidas pertencem a blocos sem resumo específico ou fora do recorte declarado. Consulte o detalhe antes de interpretar uma ausência como omissão do material.</p></section><h3>Cobertura por prova e banca</h3><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Prova / banca</th><th>Suficientes / válidas</th><th>Cobertura</th><th>Parciais</th><th>Não localizadas</th><th>Sem resumo</th><th>Pendentes</th></tr></thead><tbody>${[...new Set(qs.map(q=>data().exams.find(e=>e.id===q.examId)?.board))].flatMap(b=>[{label:b,qs:qs.filter(q=>data().exams.find(e=>e.id===q.examId)?.board===b)},...data().exams.filter(e=>e.board===b&&qs.some(q=>q.examId===e.id)).map(e=>({label:'↳ '+e.name,qs:qs.filter(q=>q.examId===e.id)}))]).map(r=>{const c=cfcMetrics(r.qs);return `<tr><th>${esc(r.label)}</th><td>${c.sufficient} / ${c.valid}</td><td>${c.pct}</td><td>${c.partial}</td><td>${c.notfound}</td><td>${c.notprovided}</td><td>${c.pending}</td></tr>`}).join('')}</tbody></table></div>`}
function cfcContentHTML(qs){const map=new Map();for(const q of qs){const key=q.area+'|'+q.topic;if(!map.has(key))map.set(key,{topic:q.topic,area:q.area,qs:[]});map.get(key).qs.push(q);}return `<h3>Quanto os resumos cobrem por conteúdo?</h3><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>Conteúdo</th><th>Suficientes / válidas</th><th>Cobertura</th><th>Parciais</th><th>Não localizadas / sem resumo</th><th>Questões</th></tr></thead><tbody>${[...map.values()].sort((a,b)=>a.topic.localeCompare(b.topic,'pt-BR')).map(g=>{const c=cfcMetrics(g.qs);return `<tr><th>${esc(g.topic)}<small>${esc(g.area)}</small></th><td>${c.sufficient} / ${c.valid}</td><td>${c.pct}</td><td>${c.partial}</td><td>${c.notfound} / ${c.notprovided}</td><td>${g.qs.map(q=>`<button class="law-open" data-q="${esc(q.id)}" title="${esc(cfcLabels[cfcInfo(q).status])}">${esc(q.examId)} Q${q.number}</button>`).join(' · ')}</td></tr>`}).join('')}</tbody></table></div>`}
function renderCFCCoverage(){renderNav();const all=selectedQuestions(),m=cfcMetrics(all),rows=all.filter(q=>!state.cfcStatus||cfcInfo(q).status===state.cfcStatus);statsHTML([[m.sufficient,'com base suficiente'],[m.partial,'com base parcial'],[m.notfound,'não localizadas nos materiais'],[m.pct,'suficientes / questões válidas']]);$('#resultCount').textContent=`${rows.length} questões exibidas · ${m.annulled} anuladas fora do índice`;$('#results').innerHTML=`${cfcSummaryHTML(all)}${cfcContentHTML(all)}<h3>Conferência por questão</h3><nav class="study-focus-filters" aria-label="Filtrar cobertura CFC">${[['','Todas'],...Object.entries(cfcLabels)].map(([value,label])=>`<button data-cfc-status="${value}" class="${(state.cfcStatus||'')===value?'active':''}">${esc(label)} <b>${value?m[value]:all.length}</b></button>`).join('')}</nav><div class="cfc-question-list">${rows.map(q=>`<article class="cfc-question"><button class="law-open" data-q="${esc(q.id)}">${esc(q.examId)} · Q${q.number} ↗</button><h4>${esc(q.topic)}</h4>${cfcBadge(q)}<p>${esc(cfcInfo(q).reason)}</p>${cfcInfo(q).missingKnowledge?`<p><b>Complementar:</b> ${esc(cfcInfo(q).missingKnowledge)}</p>`:''}<p class="save-caption">${(cfcInfo(q).summaryEvidence||[]).map(e=>`${esc(materialById(e.materialId)?.title||e.materialId)} · p. ${e.page}`).join('; ')||'Sem trecho suficiente localizado.'}</p></article>`).join('')}</div>`}
function renderCFCMaterials(){renderOrganizedMaterials()}
$('#results').addEventListener('click',e=>{const b=e.target.closest('[data-cfc-status]');if(b){state.cfcStatus=b.dataset.cfcStatus;render()}});

const primaryMaterialSubjects={'cfc-01':['AFO e Direito Financeiro'],'cfc-02':['AFO e Direito Financeiro'],'cfc-03':['Auditoria'],'cfc-04':['Contabilidade'],'cfc-05':['Contabilidade'],'cfc-06':['Direito Administrativo'],'cfc-07':['Direito Civil e Processual Civil'],'cfc-08':['Direito Constitucional'],'cfc-09':['Direito Empresarial'],'cfc-10':['Direito Penal e Processual Penal'],'cfc-11':['Estatística'],'cfc-12':['Português'],'cfc-13':['Economia e Finanças Públicas'],'cfc-14':['Matemática Financeira'],'cfc-15':['Raciocínio Lógico']};
function materialEvidence(q){return [...(q.coverage?.summaryEvidence||[]),...(q.coverage?.lawEvidence||[]),...(q.summaryCoverage?.summaryEvidence||[])]}
function materialFileGroup(m){const tax={
'e11a277903':['Direito Tributário','Conceito, natureza e espécies de tributos'],'6700938e15':['Direito Tributário','Princípios e imunidades'],'0f78cc1c35':['Direito Tributário','Competência e legislação tributária'],'6823accab0':['Direito Tributário','Obrigação e responsabilidade tributária'],'371b859de1':['Direito Tributário','Crédito tributário'],'6aa3d935c9':['Direito Tributário','Extinção do crédito tributário'],'31311813d9':['Direito Tributário','Fiscalização e repartição de receitas'],'c52517b53e':['Direito Tributário','Processo administrativo fiscal'],'2fe0fa0822':['Direito Tributário','CTN e atualizações'],'be2bac4718':['Direito Tributário','CTN e atualizações'],'407734c073':['Direito Tributário','CTN e atualizações'],'ff33b18615':['Direito Tributário','Execução fiscal'],'fb8d1dc0c6':['Direito Tributário','Sigilo de informações financeiras'],
'3f635cabb0':['LTE','ICMS'],'da88542a66':['LTE','ICMS'],'b083b82b8f':['LTE','ICMS'],'0b1bd97cc5':['LTE','ICMS'],'5ab6410607':['LTE','ICMS'],'d7e4d78b67':['LTE','ICMS'],'3988b336b2':['LTE','ICMS'],'law-kandir-upload':['LTE','ICMS'],'68d07854d8':['LTE','IPVA'],'cc58a1baf2':['LTE','ITCMD'],'9926c737c2':['LTE','ITCMD'],'25d817607f':['LTE','Simples Nacional'],'52007bfb31':['LTE','Legislação estadual do Ceará'],
'7eb5ba3450':['Tributação municipal','ISSQN'],'1584c83951':['Tributação municipal','ISSQN'],'4779ea6ce5':['Tributação municipal','IPTU'],'d7ead6cc01':['Tributação municipal','ITBI'],
'646fcefcb9':['Reforma','EC 132/2023: Constituição e transição'],'b013166b4c':['Reforma','EC 132/2023: Constituição e transição'],'03bb06a5a0':['Reforma','IBS e CBS'],'03aa884797':['Reforma','IBS e CBS'],'53b3fb3c85':['Reforma','IBS e CBS'],'6517847979':['Reforma','IBS e CBS'],'7708bf3a16':['Reforma','Imposto Seletivo'],'ba02c07dfe':['Reforma','Direitos e garantias do contribuinte'],'7511226cef':['Reforma','Processo administrativo do IBS'],'1046b3544b':['Reforma','Comitê Gestor do IBS'],'law-lc227-extract':['Reforma','LC 227/2026: texto legal']};
const cfc={'cfc-01':'Orçamento e LRF','cfc-02':'Orçamento e LRF','cfc-03':'Auditoria','cfc-04':'Contabilidade de Custos','cfc-05':'Contabilidade Geral e Avançada','cfc-06':'Direito Administrativo','cfc-07':'Direito Civil','cfc-08':'Direito Constitucional','cfc-09':'Direito Empresarial','cfc-10':'Direito Penal','cfc-11':'Estatística','cfc-12':'Língua Portuguesa','cfc-13':'Macroeconomia, Microeconomia e Finanças Públicas','cfc-14':'Matemática Financeira','cfc-15':'Raciocínio Lógico'};const g=tax[m.id];return g?{area:g[0],topic:g[1]}:{area:(primaryMaterialSubjects[m.id]||[])[0]||'Outros materiais',topic:cfc[m.id]||m.title};}
function materialGroups(subject=state.subject,search=state.search){const qs=data().questions.filter(q=>q.subject===subject&&(!state.exam||q.examId===state.exam)&&(!state.board||data().exams.find(e=>e.id===q.examId)?.board===state.board));const referenced=new Set(qs.flatMap(q=>materialEvidence(q).map(e=>e.materialId)));const materials=(base.materials||[]).filter(m=>subject==='Tributário'?m.publisher!=='Concurseiro Fora da Caixa'||referenced.has(m.id):(primaryMaterialSubjects[m.id]||[]).includes(subject)||referenced.has(m.id));const term=normalize(search.trim());const matches=m=>{const g=materialFileGroup(m);return !term||normalize([g.area,g.topic,m.title,m.filename].join(' ')).includes(term)};const canonical=materials.filter(m=>!m.duplicateOf),map=new Map();for(const m of canonical.filter(matches)){const g=materialFileGroup(m),key=JSON.stringify([g.area,g.topic]);if(!map.has(key))map.set(key,{...g,files:[],basis:'whole-file'});map.get(key).files.push({material:m})}const groups=[...map.values()].sort((a,b)=>a.area.localeCompare(b.area,'pt-BR')||a.topic.localeCompare(b.topic,'pt-BR'));for(const g of groups)g.files.sort((a,b)=>a.material.title.localeCompare(b.material.title,'pt-BR'));return{groups,materials,canonical,duplicates:materials.filter(m=>m.duplicateOf&&matches(m))};}
function safeMaterialLink(value){try{const url=new URL(String(value||'').trim());return url.protocol==='https:'&&!url.username&&!url.password?url.href:''}catch{return ''}}
function cleanMaterialLinks(value){const clean={};if(value&&typeof value==='object'&&!Array.isArray(value))for(const [id,url] of Object.entries(value)){if(id==='__proto__'||id==='constructor'||id==='prototype')continue;const valid=safeMaterialLink(url);if(valid)clean[id]=valid}return clean}
function materialLink(id){return safeMaterialLink(materialLinks[id])}
function saveMaterialLink(id,value){const raw=String(value||'').trim(),url=safeMaterialLink(raw);if(raw&&!url)return false;const previous=materialLinks[id];if(url)materialLinks[id]=url;else delete materialLinks[id];if(!persist()){if(previous)materialLinks[id]=previous;else delete materialLinks[id];return false}return true}
function materialDisplayTitle(m){const names={'2fe0fa0822':'CTN — texto legal','7eb5ba3450':'LC 116/2003 — ISSQN','25d817607f':'LC 123/2006 — Simples Nacional','be2bac4718':'LC 236/2026 — alterações no CTN','407734c073':'Direito Tributário — atualização LC 236/2026','ff33b18615':'Execuções fiscais','3f635cabb0':'ICMS — disposições constitucionais','da88542a66':'Lei Kandir — arts. 1º a 12','b083b82b8f':'Lei Kandir — arts. 13 a 18','0b1bd97cc5':'Lei Kandir — arts. 19 a 33','5ab6410607':'ICMS — LC 24/1975 e LC 160/2017','d7e4d78b67':'ICMS — LC 192/2022','3988b336b2':'ICMS — LC 227/2026, arts. 132 a 145','68d07854d8':'IPVA — disposições constitucionais','cc58a1baf2':'ITCMD — Constituição e LC 227/2026 (bloco 8A)','9926c737c2':'ITCMD — Constituição e LC 227/2026 (bloco 8B)','1584c83951':'ISSQN — resumo','4779ea6ce5':'IPTU — resumo','d7ead6cc01':'ITBI — resumo','646fcefcb9':'EC 132/2023 — resumo','b013166b4c':'EC 132/2023 — cópia do resumo','03bb06a5a0':'IBS e CBS — LC 214/2025, arts. 1º a 10','03aa884797':'IBS e CBS — LC 214/2025, arts. 11 a 26','53b3fb3c85':'IBS e CBS — LC 214/2025, arts. 27 a 57','6517847979':'IBS e CBS — LC 214/2025, arts. 58 a 83','7708bf3a16':'Imposto Seletivo — resumo','ba02c07dfe':'Código de Defesa do Contribuinte — resumo','7511226cef':'Processo administrativo do IBS — resumo','1046b3544b':'Comitê Gestor do IBS — resumo','fb8d1dc0c6':'Sigilo de informações financeiras — resumo'};return names[m.id]||m.title}
function organizedMaterialCard(f){const m=f.material,url=materialLink(m.id),title=materialDisplayTitle(m);return `<li class="material-file-row${m.kind==='law'?' is-law':''}"><div class="material-file-main">${url?`<a class="material-file-title" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ${esc(title)} no link salvo">${esc(title)} <span aria-hidden="true">↗</span></a>`:`<button class="material-file-title" data-material="${esc(m.id)}">${esc(title)}</button>`}<span class="material-page-count">${m.pageCount} ${m.pageCount===1?'página':'páginas'}</span><small>${esc(m.kind==='summary'?'Resumo · '+m.publisher:m.kind==='law'?'Lei / compilação':'Atualização / trechos')}${url?' · Link cadastrado':''}</small></div><div class="material-file-actions"><button data-material-link="${esc(m.id)}">${url?'Editar link':'Adicionar link do Drive'}</button><button data-material="${esc(m.id)}" aria-label="Ver detalhes de ${esc(title)}">Detalhes</button></div></li>`}
function renderOrganizedMaterials(){renderNav();const expanded=new Set([...$('#results').querySelectorAll('details[open][data-outline-key]')].map(d=>d.dataset.outlineKey));const m=materialGroups(),visibleIds=new Set(m.groups.flatMap(g=>g.files.map(f=>f.material.id)));statsHTML([[m.groups.length,'assuntos'],[visibleIds.size,'arquivos inteiros'],[m.canonical.filter(x=>visibleIds.has(x.id)&&x.kind==='summary').length,'resumos'],[m.duplicates.length,'cópia(s) duplicada(s)']]);$('#resultCount').textContent=`${m.groups.length} assuntos · ${visibleIds.size} arquivos · ${state.subject}`;const areas=new Map();for(const g of m.groups){if(!areas.has(g.area))areas.set(g.area,[]);areas.get(g.area).push(g)}const areaOrder=['Direito Tributário','LTE','Tributação municipal','Reforma'];const ordered=[...areas].sort((a,b)=>{const rank=x=>areaOrder.includes(x)?areaOrder.indexOf(x):99;return rank(a[0])-rank(b[0])||a[0].localeCompare(b[0],'pt-BR')});const opened=key=>state.search.trim()||expanded.has(key)?' open':'';$('#results').innerHTML=subjectStudyNotesHTML()+`<section class="materials-outline-intro"><h3>Sumário dos materiais</h3><p>Clique na divisão e no assunto para expandir. Cada lançamento corresponde a um arquivo inteiro. Adicione o link do Drive e clique no nome do arquivo para abri-lo.</p><small>Seus links ficam salvos neste navegador e acompanham o backup em Exportar / Importar.</small></section><div class="material-outline">${ordered.map(([area,gs],i)=>{const key=JSON.stringify([state.subject,area]);return `<details class="material-outline-area" data-outline-key="${esc(key)}"${opened(key)}><summary><span class="outline-number">${String(i+1).padStart(2,'0')}</span><span>${esc(area)}</span><small>${gs.length} assunto(s)</small></summary><div class="material-outline-topics">${gs.map(g=>{const key=JSON.stringify([state.subject,area,g.topic]);return `<details class="material-topic-group" data-material-topic="${esc(g.topic)}" data-outline-key="${esc(key)}"${opened(key)}><summary><span>${esc(g.topic)}</span><small>${g.files.length} arquivo(s)</small></summary><ul class="material-file-list">${g.files.map(organizedMaterialCard).join('')}</ul></details>`}).join('')}</div></details>`}).join('')}</div>${!m.groups.length?`<div class="empty"><h3>${state.search?'Nenhum arquivo encontrado.':'Nenhum material específico catalogado para esta matéria.'}</h3><p>${state.search?'Busque pelo assunto ou pelo nome do arquivo.':'Materiais de outra matéria aparecem quando foram usados na análise.'}</p></div>`:''}${m.duplicates.length?`<details class="material-topic-group"><summary>Cópias duplicadas <small>Não acrescentam conteúdo</small></summary><ul class="material-file-list">${m.duplicates.map(material=>organizedMaterialCard({material})).join('')}</ul></details>`:''}`;}
function editMaterialLink(id){const m=materialById(id);if(!m)return;modal('Link do material',`<form id="materialLinkForm"><p><strong>${esc(materialDisplayTitle(m))}</strong></p><label class="material-link-label">Link do Drive ou de outro arquivo<input id="materialLinkInput" name="materialLink" type="url" inputmode="url" placeholder="https://drive.google.com/…" value="${esc(materialLink(id))}"></label><p class="save-caption">Depois de salvar, clique no nome para abrir o link em outra aba. O acesso depende da permissão do arquivo no Drive.</p><p class="save-caption">O link fica neste navegador. Use Exportar para guardar uma cópia ou levar para outro dispositivo.</p><p class="form-error" id="materialLinkError" role="alert"></p><div class="form-actions"><button type="button" id="removeMaterialLink" class="secondary" ${materialLink(id)?'':'hidden'}>Remover link</button><button class="primary" type="submit">Salvar link</button></div></form>`);const form=$('#materialLinkForm'),input=$('#materialLinkInput');input.focus();const finish=value=>{if(!saveMaterialLink(id,value)){$('#materialLinkError').textContent='Não foi possível salvar. Use um endereço https:// válido e confira o armazenamento do navegador.';return}$('#modal').close();render();toast(value.trim()?'Link salvo. Clique no nome do material para abrir.':'Link removido.')};form.onsubmit=e=>{e.preventDefault();finish(input.value)};$('#removeMaterialLink').onclick=()=>finish('')}
$('#results').addEventListener('click',e=>{const b=e.target.closest('[data-material-link]');if(b)editMaterialLink(b.dataset.materialLink)});

function accountingQuestionClass(q){return q.subject==='Contabilidade'&&q.accountingType==='theory'?'accounting-theory':''}
function accountingTheoryOverview(qs){if(state.subject!=='Contabilidade')return '';const exams=data().exams.filter(e=>qs.some(q=>q.examId===e.id));const percentage=c=>c.valid?(100*c.theory/c.valid).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':'—';return `<section class="accounting-theory-overview" aria-labelledby="accountingTheoryHeading"><div class="accounting-theory-heading"><h3 id="accountingTheoryHeading">Questões só de teoria por prova</h3><span class="accounting-theory-key"><i aria-hidden="true"></i>Lilás = só teoria</span></div><div class="accounting-theory-toolbar"><button class="secondary accounting-compare-button" data-accounting-theory-toggle aria-expanded="${state.accountingTheoryOpen?'true':'false'}" aria-controls="accountingTheoryComparison">${state.accountingTheoryOpen?'Ocultar quadro comparativo':'Comparar assuntos teóricos'}</button></div><div class="accounting-theory-grid">${exams.map(e=>{const c=accountingCounts(qs.filter(q=>q.examId===e.id));return `<article class="accounting-theory-stat" data-theory-exam="${esc(e.id)}"><div><strong>${esc(e.name)}</strong><small>${esc(e.board)} · ${esc(e.year)}</small></div><b>${percentage(c)}</b><span>${c.theory} de ${c.valid} questões válidas</span></article>`}).join('')}</div><p class="save-caption">Percentual = questões só de teoria ÷ questões válidas de Contabilidade da prova neste filtro. Mistas ficam fora das teóricas; anuladas e desatualizadas ficam fora do cálculo.</p>${accountingTheoryComparison(qs)}</section>`}

function accountingTheoryComparison(qs){const valid=qs.filter(q=>q.subject==='Contabilidade'&&q.accountingType==='theory'&&!['Anulada','Desatualizada'].includes(q.answer)),exams=data().exams.filter(e=>qs.some(q=>q.examId===e.id));const groups=new Map();for(const q of valid){const key=JSON.stringify([q.area,q.topic]);if(!groups.has(key))groups.set(key,{area:q.area,topic:q.topic,questions:[]});groups.get(key).questions.push(q)}const rows=[...groups.values()].sort((a,b)=>a.topic.localeCompare(b.topic,'pt-BR')||a.area.localeCompare(b.area,'pt-BR'));return `<div id="accountingTheoryComparison" class="accounting-theory-comparison" ${state.accountingTheoryOpen?'':'hidden'}><h3>Quadro comparativo dos assuntos teóricos</h3><p>${rows.length} assunto(s) · ${valid.length} questões só de teoria. Cada coluna corresponde a uma prova; clique no número para abrir a questão. O quadro acompanha os filtros selecionados e exclui questões mistas, anuladas e desatualizadas.</p>${rows.length?`<div class="coverage-table-wrap accounting-theory-table"><table class="coverage-table"><thead><tr><th scope="col">Assunto teórico</th>${exams.map(e=>`<th scope="col">${esc(e.name)}<small>${esc(e.board)} · ${esc(e.year)}</small></th>`).join('')}<th scope="col">Total</th></tr></thead><tbody>${rows.map(g=>`<tr><th scope="row">${esc(g.topic)}<small>${esc(g.area)}</small></th>${exams.map(e=>{const questions=g.questions.filter(q=>q.examId===e.id).sort((a,b)=>a.number-b.number);return `<td>${questions.length?`<span class="theory-cell-count">${questions.length} questão(ões)</span><div class="theory-question-links">${questions.map(q=>`<button class="theory-question-link" data-q="${esc(q.id)}" title="${esc(q.summary)}">Q${q.number}</button>`).join('')}</div>`:'<span class="dash" aria-label="Nenhuma questão só de teoria neste assunto">—</span>'}</td>`}).join('')}<td><strong>${g.questions.length}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h4>Nenhuma questão só de teoria neste filtro.</h4><p>Amplie o assunto ou selecione mais provas.</p></div>'}</div>`}
function toggleAccountingTheory(){state.accountingTheoryOpen=!state.accountingTheoryOpen;render();$('#results [data-accounting-theory-toggle]')?.focus()}
$('#results').addEventListener('click',e=>{if(e.target.closest('[data-accounting-theory-toggle]'))toggleAccountingTheory()});

function matchingStudyNotes(item){return (base.studyNotes||[]).filter(n=>n.subject===(item.subject||state.subject)&&n.topicPrefixes.some(p=>normalize(item.topic||'').startsWith(normalize(p))))}
function topicStudyTitle(item){const note=matchingStudyNotes(item)[0];return note?`<a class="topic-study-title" href="${esc(note.panelUrl)}">${esc(item.topic)}</a><small class="topic-study-caption">Anotação disponível · clique no assunto</small>`:esc(item.topic)}
function topicStudyLinks(item){return matchingStudyNotes(item).map(n=>`<div class="topic-study-links"><a href="${esc(n.panelUrl)}">Ler anotação de ${esc(n.topic)}</a><a href="${esc(n.driveUrl)}" target="_blank" rel="noopener noreferrer">Documento no Drive ↗</a></div>`).join('')}
function subjectStudyNotesHTML(){const notes=(base.studyNotes||[]).filter(n=>n.subject===state.subject);return notes.length?`<section class="subject-study-notes"><h3>Minhas anotações por assunto</h3>${notes.map(n=>`<div class="topic-study-links"><a href="${esc(n.panelUrl)}">${esc(n.title)}</a><a href="${esc(n.driveUrl)}" target="_blank" rel="noopener noreferrer">Abrir no Drive ↗</a></div>`).join('')}</section>`:''}

const portugueseInterpretationTopics=new Set(['Interpretação: informações e inferências','Interpretação: ideia central e argumentos','Interpretação: organização e relações entre partes','Vocabulário e equivalência de expressões','Vocabulário e análise contextual de palavras','Relações lógico-semânticas e conectores','Figuras de linguagem e sentido figurado']);
function portugueseIncidenceTopic(q){return portugueseInterpretationTopics.has(q.topic)?'Interpretação e valor semântico':q.topic||'Sem classificação'}
function portugueseIncidenceModel(qs,exams){const questions=qs.filter(q=>q.subject==='Português'),totals=new Map(exams.map(e=>[e.id,questions.filter(q=>q.examId===e.id).length])),groups=new Map();for(const q of questions){const topic=portugueseIncidenceTopic(q);if(!groups.has(topic))groups.set(topic,{topic,questions:[],originalTopics:new Set()});const g=groups.get(topic);g.questions.push(q);g.originalTopics.add(q.topic)}return {total:questions.length,totals,exams,rows:[...groups.values()].sort((a,b)=>b.questions.length-a.questions.length||a.topic.localeCompare(b.topic,'pt-BR'))}}
function portugueseIncidenceOverview(){if(state.subject!=='Português')return '';const exams=currentExams(),ids=new Set(exams.map(e=>e.id)),qs=data().questions.filter(q=>q.subject==='Português'&&ids.has(q.examId)),m=portugueseIncidenceModel(qs,exams);if(!m.total)return '';const cell=(n,total)=>total?`<strong>${(100*n/total).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}%</strong><small>${n} de ${total}</small>`:'<span class="dash">—</span>';return `<section class="portuguese-incidence" aria-labelledby="portugueseIncidenceHeading"><h3 id="portugueseIncidenceHeading">Português: percentual por assunto</h3><p>${m.total} questões em ${exams.length} prova(s). Interpretação e valor semântico aparecem juntos.</p><div class="coverage-table-wrap portuguese-incidence-table"><table class="coverage-table"><thead><tr><th scope="col">Assunto</th><th scope="col">Geral<small>${m.total} questões</small></th>${exams.map(e=>`<th scope="col">${esc(e.name)}<small>${esc(e.board)} · ${esc(e.year)}</small></th>`).join('')}</tr></thead><tbody>${m.rows.map(g=>`<tr${g.topic==='Interpretação e valor semântico'?' class="portuguese-interpretation-row"':''}><th scope="row">${esc(g.topic)}</th><td>${cell(g.questions.length,m.total)}</td>${exams.map(e=>`<td>${cell(g.questions.filter(q=>q.examId===e.id).length,m.totals.get(e.id))}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th scope="row">Total de Português</th><td>${cell(m.total,m.total)}</td>${exams.map(e=>`<td>${cell(m.totals.get(e.id),m.totals.get(e.id))}</td>`).join('')}</tr></tfoot></table></div><p class="save-caption">Percentual = questões do assunto ÷ total de Português da coluna. O geral soma as questões das provas selecionadas. Cada questão conta uma vez, pelo assunto principal; inclui anuladas, pois mede incidência de cobrança. A base acompanha os filtros de banca e prova. Diferenças na soma podem decorrer do arredondamento.</p><details class="portuguese-incidence-method"><summary>O que entra em interpretação e valor semântico?</summary><p>Compreensão, inferências, ideia central, argumentos e organização do texto; significado contextual de palavras, equivalência de expressões, figuras de linguagem, sentido figurado e relações lógico-semânticas de conectores. Coesão, reescrita e demais conteúdos gramaticais mantêm o assunto principal já atribuído a cada questão.</p></details></section>`}

function applyInitialRoute(){const params=new URLSearchParams(globalThis.location?.search||'');if(params.get('materia')==='portugues'){Object.assign(state,{subject:'Português',area:'Todas',page:params.get('aba')==='relatorio'?'reports':'map',board:'',exam:'',search:'',common:false})}}
applyInitialRoute();
render();
